import * as nodePath from "node:path";
import type { DirEntry, FileSystem } from "./filesystem.js";

/**
 * In-memory file-system backed by a `Map<string, string>`.
 *
 * Designed for unit tests. Every operation is synchronous and never touches
 * the real disk. Directory markers are stored as keys ending with `/`.
 * `realpath` returns the input unchanged — there are no symlinks in memory.
 * `resolve` uses `node:path` so that `.` and `..` segments are normalised
 * correctly without any real I/O.
 */
export class InMemoryFileSystem implements FileSystem {
  private readonly store = new Map<string, string>();
  private readonly mtimes = new Map<string, number>();
  private mtimeCounter = 0;

  readFile(path: string): string {
    if (!this.store.has(path)) {
      throw new Error(`ENOENT: no such file or directory: '${path}'`);
    }
    return this.store.get(path) as string;
  }

  writeFile(path: string, content: string): void {
    this.store.set(path, content);
    this.touch(path);
  }

  exists(path: string): boolean {
    if (this.store.has(path)) return true;
    const prefix = path.endsWith("/") ? path : `${path}/`;
    for (const key of this.store.keys()) {
      if (key.startsWith(prefix)) return true;
    }
    return false;
  }

  mkdir(path: string, _options?: { recursive?: boolean }): void {
    const marker = path.endsWith("/") ? path : `${path}/`;
    this.store.set(marker, "");
    this.touch(marker);
  }

  rename(oldPath: string, newPath: string): void {
    if (this.store.has(oldPath)) {
      const content = this.store.get(oldPath) as string;
      this.store.delete(oldPath);
      this.mtimes.delete(oldPath);
      this.store.set(newPath, content);
      this.touch(newPath);
      return;
    }
    if (this.isDirectory(oldPath)) {
      this.renameDirectory(oldPath, newPath);
      return;
    }
    throw new Error(`ENOENT: no such file or directory: '${oldPath}'`);
  }

  /**
   * `node:fs.renameSync` relocates a whole subtree, and operations that move a
   * directory depend on that. Keys are flat here, so the subtree is rewritten
   * prefix by prefix. A directory marker is just another key under the prefix,
   * so it moves with everything else; a directory inferred from its children
   * has no marker and needs none, because the moved children still imply it.
   */
  private renameDirectory(oldPath: string, newPath: string): void {
    const oldPrefix = oldPath.endsWith("/") ? oldPath : `${oldPath}/`;
    const newPrefix = newPath.endsWith("/") ? newPath : `${newPath}/`;

    for (const key of [...this.store.keys()]) {
      if (!key.startsWith(oldPrefix)) continue;
      const moved = newPrefix + key.slice(oldPrefix.length);
      this.store.set(moved, this.store.get(key) as string);
      this.store.delete(key);
      this.mtimes.delete(key);
      this.touch(moved);
    }
  }

  unlink(path: string): void {
    if (!this.store.has(path)) {
      throw new Error(`ENOENT: no such file or directory: '${path}'`);
    }
    this.store.delete(path);
    this.mtimes.delete(path);
  }

  realpath(path: string): string {
    return path;
  }

  resolve(...segments: string[]): string {
    return nodePath.resolve(...segments);
  }

  stat(path: string): { isDirectory(): boolean; mtimeMs: number } {
    if (!this.exists(path)) {
      throw new Error(`ENOENT: no such file or directory, stat '${path}'`);
    }
    const isDir = this.isDirectory(path);
    const marker = path.endsWith("/") ? path : `${path}/`;
    const mtimeMs = this.mtimes.get(path) ?? this.mtimes.get(marker) ?? 0;
    return { isDirectory: () => isDir, mtimeMs };
  }

  /**
   * Bumps the path's stamp using a monotonic counter rather than a real
   * clock — every mutation is a distinct tick, so callers only ever need to
   * compare stamps for ordering, never their magnitude.
   */
  private touch(path: string): void {
    this.mtimeCounter += 1;
    this.mtimes.set(path, this.mtimeCounter);
  }

  readdir(path: string): DirEntry[] {
    if (!this.isDirectory(path)) {
      throw new Error(`ENOTDIR: not a directory: '${path}'`);
    }
    const prefix = path.endsWith("/") ? path : `${path}/`;
    // A child is a directory if any key nests below it (has a further slash),
    // otherwise a plain file. Collecting into sets keeps this order-independent
    // and lets directory classification win when a name appears as both.
    const dirs = new Set<string>();
    const files = new Set<string>();
    for (const key of this.store.keys()) {
      if (!key.startsWith(prefix)) continue;
      const rest = key.slice(prefix.length);
      if (rest === "") continue; // the directory's own marker key
      const slash = rest.indexOf("/");
      if (slash === -1) files.add(rest);
      else dirs.add(rest.slice(0, slash));
    }
    return [...new Set([...dirs, ...files])].map((name) => {
      const isDir = dirs.has(name);
      return { name, isDirectory: () => isDir, isFile: () => !isDir };
    });
  }

  private isDirectory(path: string): boolean {
    if (path.endsWith("/")) return true;
    const prefix = `${path}/`;
    for (const key of this.store.keys()) {
      if (key.startsWith(prefix)) return true;
    }
    return false;
  }
}

src/ts-engine/move-directory.ts.source:
import * as path from "node:path";
import type { WorkspaceScope } from "../domain/workspace-scope.js";
import type { FileSystem } from "../ports/filesystem.js";
import { TS_EXTENSIONS } from "../utils/extensions.js";
import { walkRecursive } from "../utils/file-walk.js";
import { tsAfterFileRename } from "./after-file-rename.js";
import { applyRenameEdits, mergeFileEdits } from "./apply-rename-edits.js";
import type { TsMorphEngine } from "./engine.js";
import type { FileTextEdit } from "./types.js";

/**
 * Full moveDirectory workflow for TypeScript/JavaScript projects.
 *
 * Computes import edits for all source files before any physical move,
 * applies external edits, atomically renames the directory on disk, updates
 * the project graph for each moved source file, and records all moved files
 * (source and non-source) in scope.
 *
 * Precondition: `oldPath` must exist and be a valid directory.
 */
export async function tsMoveDirectory(
  engine: TsMorphEngine,
  oldPath: string,
  newPath: string,
  scope: WorkspaceScope,
): Promise<{ filesMoved: string[] }> {
  const absOld = path.resolve(oldPath);
  const absNew = path.resolve(newPath);
  const project = engine.getProjectForDirectory(absOld);

  const sourceFiles = enumerateSourceFiles(absOld, scope.fs);
  for (const filePath of sourceFiles) {
    if (!project.getSourceFile(filePath)) {
      project.addSourceFileAtPath(filePath);
    }
  }

  const mappings = sourceFiles.map((oldFilePath) => ({
    oldFilePath,
    newFilePath: path.join(absNew, path.relative(absOld, oldFilePath)),
  }));

  const allEdits: FileTextEdit[][] = [];
  for (const { oldFilePath, newFilePath } of mappings) {
    allEdits.push(await engine.getEditsForFileRename(oldFilePath, newFilePath));
  }

  // Filter out edits targeting files inside the moved directory — the language
  // service doesn't know about the batch move and would corrupt intra-directory
  // specifiers that are still valid after the move.
  const externalEdits = mergeFileEdits(allEdits).filter(
    (e) => !e.fileName.startsWith(absOld + path.sep) && e.fileName !== absOld,
  );
  applyRenameEdits(engine, externalEdits, scope);

  scope.fs.mkdir(path.dirname(absNew), { recursive: true });
  scope.fs.rename(absOld, absNew);

  for (const { oldFilePath, newFilePath } of mappings) {
    await tsAfterFileRename(engine, oldFilePath, newFilePath, scope);
  }

  // Enumerate all files now at absNew (source + non-source, skipping SKIP_DIRS)
  const filesMoved: string[] = [];
  for (const newFilePath of walkRecursive(absNew, scope.fs)) {
    scope.recordModified(newFilePath);
    filesMoved.push(newFilePath);
  }

  return { filesMoved };
}

/**
 * Deliberately walks recursively rather than via `walkFiles`, which would drop
 * gitignored files: a generated-but-ignored source file inside the moved
 * directory still imports its neighbours, and those imports still need
 * rewriting. Untracked files are not the difference — `git ls-files --others`
 * reports those either way.
 */
function enumerateSourceFiles(dir: string, fs: FileSystem): string[] {
  return walkRecursive(dir, fs).filter((f) => TS_EXTENSIONS.has(path.extname(f)));
}

src/ts-engine/persist-source-file.ts.source:
import type { SourceFile } from "ts-morph";
import type { WorkspaceScope } from "../domain/workspace-scope.js";

const BOM = "\uFEFF";

/**
 * Separates a leading byte-order mark from the text that follows it, so
 * content can be rewritten or prefixed without the mark drifting away from
 * byte 0. A mark left mid-file is worse than a missing one: it stops being
 * an encoding hint and becomes a stray character in the source.
 */
export function splitLeadingBom(text: string): { bom: string; body: string } {
  return text.startsWith(BOM)
    ? { bom: BOM, body: text.slice(BOM.length) }
    : { bom: "", body: text };
}

/**
 * Persist a ts-morph `SourceFile` to disk through the workspace's `FileSystem`
 * port, in place of `SourceFile#save()`.
 *
 * `save()` writes `getFullText()` prefixed with a byte-order mark when the
 * file was originally read with one; `getFullText()` itself never includes
 * it, and ts-morph exposes no public way to ask a `SourceFile` whether it had
 * one. This checks the on-disk bytes directly, before this call overwrites
 * them, so a BOM present on disk is carried forward.
 */
export function persistSourceFile(sf: SourceFile, scope: WorkspaceScope): void {
  const filePath = sf.getFilePath() as string;
  const hadBom = scope.fs.exists(filePath) && scope.fs.readFile(filePath).startsWith(BOM);
  const text = sf.getFullText();
  scope.writeFile(filePath, hadBom ? `${BOM}${text}` : text);
}

