import * as fs from "node:fs";
import * as path from "node:path";
import type ts from "typescript";
import { EngineError } from "../../domain/errors.js";
import type { WorkspaceScope } from "../../domain/workspace-scope.js";
import type { GetTypeErrorsResult, RenameResult, SetExportResult } from "../../operations/types.js";
import { applyRenameEdits, mergeFileEdits } from "../../ts-engine/apply-rename-edits.js";
import type { TsMorphEngine } from "../../ts-engine/engine.js";
import { isCoexistingJsFileEdit } from "../../ts-engine/rewrite-importers-of-moved-file.js";
import { tsSetExport } from "../../ts-engine/set-export.js";
import type {
  DefinitionLocation,
  DeleteFileActionResult,
  Engine,
  ExtractFunctionResult,
  FileTextEdit,
  MoveFileActionResult,
  SpanLocation,
} from "../../ts-engine/types.js";
import { walkRecursive } from "../../utils/file-walk.js";
import { applyTextEdits, lineColToOffset } from "../../utils/text-utils.js";
import { findTsConfig, findTsConfigForFile } from "../../utils/ts-project.js";
import { vueDeleteFile } from "./delete-file.js";
import { vueExtractFunction } from "./extract-function.js";
import {
  vueGetTypeErrorsForFile,
  vueGetTypeErrorsForProject,
  vueGetTypeErrorsForTsFile,
} from "./get-type-errors.js";
import { vueMoveFile, vueRenameEdits } from "./move-file.js";
import { vueMoveSymbol } from "./move-symbol.js";
import { scanVueNameMatches } from "./name-matches.js";
import {
  rewriteVueOwnImportsAfterMove,
  updateVueImportsAfterMove,
  updateVueImportsAfterSymbolMove,
  vueScriptsReferencingSymbol,
} from "./scan.js";
import { buildVolarService, type CachedService, toVirtualVuePath } from "./service.js";

export class VolarEngine implements Engine {
  private services = new Map<string, CachedService>();
  private tsEngine: TsMorphEngine;
  private workspaceRoot: string;

  constructor(tsEngine: TsMorphEngine, workspaceRoot = "") {
    this.tsEngine = tsEngine;
    this.workspaceRoot = workspaceRoot;
  }

  private cacheKey(
    tsConfigPath: string | null,
    filePath: string | undefined,
    root: string = this.workspaceRoot,
  ): string {
    return tsConfigPath ?? `__no_tsconfig__:${filePath ? path.dirname(filePath) : root}`;
  }

  // `filePath` is undefined for project-wide operations (e.g. a project-wide getTypeErrors)
  // with no specific target file — see findTsConfig vs findTsConfigForFile in docs/architecture.md.
  // `root` is the request's own workspace root (fresh per call, e.g. scope.root), not
  // `this.workspaceRoot` — this engine instance is cached and reused for the lifetime of the
  // daemon process, so `this.workspaceRoot` reflects whatever workspace first constructed it.
  // In production that never differs (one daemon per workspace), but the two are not the same
  // thing, and only `root` is guaranteed current.
  //
  // `explicitTsConfig`, when given, names the tsconfig to build the service for directly —
  // it wins over both discovery routes, for the same reason as `makeRegistry`'s parameter of
  // the same name: a caller that named a tsconfig (e.g. `getTypeErrors`'s `tsconfig` param)
  // wants that config's own service, not whichever one discovery would have found.
  private async getService(
    filePath: string | undefined,
    root: string = this.workspaceRoot,
    explicitTsConfig?: string,
  ): Promise<CachedService> {
    const tsConfigPath =
      explicitTsConfig ?? (filePath ? findTsConfigForFile(filePath) : findTsConfig(root));
    const cacheKey = this.cacheKey(tsConfigPath, filePath, root);

    let cached = this.services.get(cacheKey);
    if (!cached) {
      cached = await buildVolarService(tsConfigPath, filePath, root || undefined);
      this.services.set(cacheKey, cached);
    }
    return cached;
  }

  invalidateService(filePath: string): void {
    const tsConfigPath = findTsConfigForFile(filePath);
    this.services.delete(this.cacheKey(tsConfigPath, filePath));
  }

  // Volar has no per-file refresh: the cached service is rebuilt whole, so callers
  // that refresh several files should do so before querying any of them.
  refreshFile(filePath: string): void {
    this.invalidateService(filePath);
  }

  // ─── Virtual ↔ real path helpers ──────────────────────────────────────────

  private toVirtualLocation(
    realPath: string,
    pos: number,
    service: CachedService,
  ): { fileName: string; pos: number } {
    if (!realPath.endsWith(".vue")) return { fileName: realPath, pos };

    const virtualPath = `${realPath}.ts`;
    if (!service.vueVirtualToReal.has(virtualPath)) return { fileName: realPath, pos };

    const sourceScript = service.language.scripts.get(realPath);
    if (!sourceScript?.generated) return { fileName: virtualPath, pos };

    const serviceScript = sourceScript.generated.languagePlugin.typescript?.getServiceScript(
      sourceScript.generated.root,
    );
    if (!serviceScript) return { fileName: virtualPath, pos };

    const mapper = service.language.maps.get(serviceScript.code, sourceScript);
    const iter = mapper.toGeneratedLocation(pos);
    const next = iter.next() as IteratorResult<readonly [number, unknown]>;
    if (!next.done) return { fileName: virtualPath, pos: next.value[0] };

    return { fileName: virtualPath, pos };
  }

  private translateSingleLocation(loc: SpanLocation, service: CachedService): SpanLocation | null {
    const realVuePath = service.vueVirtualToReal.get(loc.fileName);
    if (realVuePath === undefined) return loc;

    const sourceScript = service.language.scripts.get(realVuePath);
    if (!sourceScript?.generated) return { fileName: realVuePath, textSpan: loc.textSpan };

    const serviceScript = sourceScript.generated.languagePlugin.typescript?.getServiceScript(
      sourceScript.generated.root,
    );
    if (!serviceScript) return { fileName: realVuePath, textSpan: loc.textSpan };

    const mapper = service.language.maps.get(serviceScript.code, sourceScript);
    const iter = mapper.toSourceLocation(loc.textSpan.start);
    const next = iter.next() as IteratorResult<readonly [number, unknown]>;
    if (!next.done) {
      const [sourceOffset] = next.value;
      return {
        fileName: realVuePath,
        textSpan: { start: sourceOffset, length: loc.textSpan.length },
      };
    }
    // No source mapping — Volar glue code; exclude from results.
    return null;
  }

  private translateLocations(
    rawLocations: readonly SpanLocation[],
    service: CachedService,
  ): SpanLocation[] {
    return rawLocations
      .map((loc) => this.translateSingleLocation(loc, service))
      .filter((loc): loc is SpanLocation => loc !== null);
  }

  // ─── Compiler ─────────────────────────────────────────────────────

  resolveOffset(file: string, line: number, col: number): number {
    const content = fs.readFileSync(file, "utf8");
    try {
      return lineColToOffset(content, line, col);
    } catch {
      throw new EngineError(`Line ${line} out of range in ${file}`, "SYMBOL_NOT_FOUND");
    }
  }

  async getRenameLocations(file: string, offset: number): Promise<SpanLocation[] | null> {
    const service = await this.getService(file);
    // Refresh content so the language service sees any recent edits.
    service.fileContents.set(file, fs.readFileSync(file, "utf8"));

    const { fileName, pos } = this.toVirtualLocation(file, offset, service);
    const rawLocs = service.languageService.findRenameLocations(fileName, pos, false, false, {});
    if (!rawLocs || rawLocs.length === 0) return null;

    return this.translateLocations(rawLocs, service);
  }

  async getReferencesAtPosition(file: string, offset: number): Promise<SpanLocation[] | null> {
    const service = await this.getService(file);
    service.fileContents.set(file, fs.readFileSync(file, "utf8"));

    const { fileName, pos } = this.toVirtualLocation(file, offset, service);
    const rawRefs = service.languageService.getReferencesAtPosition(fileName, pos);
    if (!rawRefs || rawRefs.length === 0) return null;

    return this.translateLocations(rawRefs, service);
  }

  async getFileReferences(file: string): Promise<SpanLocation[] | null> {
    const service = await this.getService(file);

    // For .vue targets, query the virtual .vue.ts path so the TS language
    // service can find references to it in both .ts and .vue files.
    const queryPath = toVirtualVuePath(file);

    const refs = service.baseService.getFileReferences(queryPath);
    if (!refs || refs.length === 0) return null;

    const rawLocs: SpanLocation[] = refs.map((ref) => ({
      fileName: ref.fileName,
      textSpan: { start: ref.textSpan.start, length: ref.textSpan.length },
    }));

    return this.translateLocations(rawLocs, service);
  }

  async getDefinitionAtPosition(
    file: string,
    offset: number,
  ): Promise<DefinitionLocation[] | null> {
    const service = await this.getService(file);
    service.fileContents.set(file, fs.readFileSync(file, "utf8"));

    const { fileName: queryFile, pos: queryPos } = this.toVirtualLocation(file, offset, service);

    const rawDefs = service.languageService.getDefinitionAtPosition(queryFile, queryPos);
    if (!rawDefs || rawDefs.length === 0) return null;

    const symbolName = rawDefs[0].name;
    const defs = this.translateLocations(rawDefs, service);

    return defs.map((def) => ({ ...def, name: symbolName }));
  }

  /**
   * Restate one language-service edit against the file a caller can write.
   *
   * An edit naming a virtual `<name>.vue.ts` carries offsets into generated TypeScript, so
   * each change is mapped back onto the SFC's own source. A change with no mapping sits in
   * Volar's glue code and belongs to no source file, so it is dropped rather than written.
   */
  private toRealFileEdit(edit: ts.FileTextChanges, service: CachedService): FileTextEdit {
    const fileName = service.vueVirtualToReal.get(edit.fileName) ?? edit.fileName;
    return {
      fileName,
      textChanges: edit.textChanges.flatMap((change) => {
        const source = this.translateSingleLocation(
          { fileName: edit.fileName, textSpan: change.span },
          service,
        );
        if (source === null) return [];
        const span = { start: source.textSpan.start, length: source.textSpan.length };
        if (isCoexistingJsFileEdit(fileName, span.start, span.length)) return [];
        return [{ span, newText: change.newText }];
      }),
    };
  }

  /**
   * `targets` narrows which files are worth translating at all. Everything outside it would be
   * built, disk-checked for a coexisting `.js`, and then discarded by the caller — so a move
   * that only wants SFC edits reads every `.ts` importer for nothing.
   */
  async getEditsForFileRename(
    oldPath: string,
    newPath: string,
    targets: (fileName: string) => boolean = () => true,
  ): Promise<FileTextEdit[]> {
    const service = await this.getService(oldPath);
    const edits = service.languageService.getEditsForFileRename(oldPath, newPath, {}, {});

    return edits
      .filter((e) => targets(service.vueVirtualToReal.get(e.fileName) ?? e.fileName))
      .map((e) => this.toRealFileEdit(e, service))
      .filter((e) => e.textChanges.length > 0);
  }

  readFile(filePath: string): string {
    // Check the service cache first (may already have content loaded by buildService).
    const tsConfigPath = findTsConfigForFile(filePath);
    const cached = this.services.get(this.cacheKey(tsConfigPath, filePath));
    return cached?.fileContents.get(filePath) ?? fs.readFileSync(filePath, "utf8");
  }

  notifyFileWritten(filePath: string, content: string): void {
    const tsConfigPath = findTsConfigForFile(filePath);
    const cached = this.services.get(this.cacheKey(tsConfigPath, filePath));
    if (cached) cached.fileContents.set(filePath, content);
  }

  async moveSymbol(
    sourceFile: string,
    symbolName: string,
    destFile: string,
    scope: WorkspaceScope,
    options?: { force?: boolean },
  ): Promise<void> {
    if (sourceFile.endsWith(".vue")) {
      await vueMoveSymbol(sourceFile, symbolName, destFile, scope, options);
      return;
    }
    // Delegate TS work (AST surgery + fallback scan for out-of-project TS/JS files).
    await this.tsEngine.moveSymbol(sourceFile, symbolName, destFile, scope, options);

    // Vue SFC scanning: walk .vue files and rewrite imports in <script> blocks.
    const tsConfig = findTsConfigForFile(sourceFile);
    const searchRoot = tsConfig ? path.dirname(tsConfig) : scope.root;
    updateVueImportsAfterSymbolMove(symbolName, sourceFile, destFile, searchRoot, scope);
  }

  async moveFile(
    oldPath: string,
    newPath: string,
    scope: WorkspaceScope,
  ): Promise<MoveFileActionResult> {
    return vueMoveFile(this, this.tsEngine, oldPath, newPath, scope);
  }

  async moveDirectory(
    oldPath: string,
    newPath: string,
    scope: WorkspaceScope,
  ): Promise<{ filesMoved: string[] }> {
    const absOld = path.resolve(oldPath);
    const absNew = path.resolve(newPath);

    const allFiles = walkRecursive(absOld);
    const allMappings = allFiles.map((oldFilePath) => ({
      oldFilePath,
      newFilePath: path.join(absNew, path.relative(absOld, oldFilePath)),
    }));
    const vueMappings = allMappings.filter(({ oldFilePath }) => oldFilePath.endsWith(".vue"));

    // Must resolve before the physical move — absOld won't exist after.
    const tsConfig = findTsConfigForFile(absOld);
    const searchRoot = tsConfig ? path.dirname(tsConfig) : scope.root;

    // Run before the move — the service has to see each old path on disk.
    const editSets = await Promise.all(
      vueMappings.map(({ oldFilePath, newFilePath }) =>
        vueRenameEdits(this, oldFilePath, newFilePath),
      ),
    );
    applyRenameEdits(this, mergeFileEdits(editSets), scope);

    const result = await this.tsEngine.moveDirectory(absOld, absNew, scope);
    this.invalidateService(absOld);

    for (const { oldFilePath, newFilePath } of allMappings) {
      updateVueImportsAfterMove(oldFilePath, newFilePath, searchRoot, scope);
    }

    // getEditsForFileRename does not cover own-import rewriting for moved .vue files.
    for (const { oldFilePath, newFilePath } of vueMappings) {
      rewriteVueOwnImportsAfterMove(oldFilePath, newFilePath, scope);
    }

    return result;
  }

  async deleteFile(targetFile: string, scope: WorkspaceScope): Promise<DeleteFileActionResult> {
    return vueDeleteFile(this.tsEngine, targetFile, scope);
  }

  async setExport(
    file: string,
    symbolName: string,
    exported: boolean,
    scope: WorkspaceScope,
  ): Promise<SetExportResult> {
    if (file.endsWith(".vue")) {
      throw new EngineError(
        `Cannot change the visibility of '${symbolName}' in ${file}: a top-level export is not valid inside a Vue SFC script block.`,
        "NOT_SUPPORTED",
      );
    }

    const tsConfig = findTsConfigForFile(file);
    const searchRoot = tsConfig ? path.dirname(tsConfig) : scope.root;
    const vueReferences = exported
      ? []
      : vueScriptsReferencingSymbol(symbolName, file, searchRoot, scope);

    return tsSetExport(this.tsEngine, file, symbolName, exported, scope, vueReferences);
  }

  async extractFunction(
    file: string,
    startLine: number,
    startCol: number,
    endLine: number,
    endCol: number,
    functionName: string,
    scope: WorkspaceScope,
  ): Promise<ExtractFunctionResult> {
    if (file.endsWith(".vue")) {
      const result = vueExtractFunction(
        file,
        startLine,
        startCol,
        endLine,
        endCol,
        functionName,
        scope,
      );
      this.invalidateService(file);
      return result;
    }
    return this.tsEngine.extractFunction(
      file,
      startLine,
      startCol,
      endLine,
      endCol,
      functionName,
      scope,
    );
  }

  async getTypeErrors(
    file: string | undefined,
    scope: WorkspaceScope,
    tsConfigPath?: string,
  ): Promise<GetTypeErrorsResult> {
    if (file !== undefined) {
      if (file.endsWith(".vue")) {
        return vueGetTypeErrorsForFile(file, (f) => this.getService(f));
      }
      // .ts/.tsx file in a Vue project — the Volar service resolves .vue
      // imports the ts-morph project cannot; see scope.root note above.
      return vueGetTypeErrorsForTsFile(file, (f) => this.getService(f, scope.root));
    }
    // Project-wide, answered entirely by the Volar service (both file kinds).
    // Root comes from the request's scope, not this.workspaceRoot — see
    // getService's doc comment for why that distinction matters. tsConfigPath, when
    // given, is the caller's own named config — see getService's doc comment on
    // explicitTsConfig for why it wins over discovery from scope.root.
    const resolvedTsConfig = tsConfigPath ?? findTsConfig(scope.root);
    return vueGetTypeErrorsForProject(
      (f) => this.getService(f, scope.root, tsConfigPath),
      resolvedTsConfig,
      scope.root,
    );
  }

  async rename(
    file: string,
    line: number,
    col: number,
    newName: string,
    scope: WorkspaceScope,
  ): Promise<RenameResult> {
    const service = await this.getService(file);
    const offset = this.resolveOffset(file, line, col);
    const locs = await this.getRenameLocations(file, offset);

    if (!locs) {
      throw new EngineError(
        `No renameable symbol at line ${line}, col ${col} in ${file}`,
        "SYMBOL_NOT_FOUND",
      );
    }

    const firstLoc = locs[0];
    const firstContent = this.readFile(firstLoc.fileName);
    const oldName = firstContent.slice(
      firstLoc.textSpan.start,
      firstLoc.textSpan.start + firstLoc.textSpan.length,
    );

    const editsByFile = new Map<
      string,
      { span: { start: number; length: number }; newText: string }[]
    >();
    for (const loc of locs) {
      let fileEdits = editsByFile.get(loc.fileName);
      if (!fileEdits) {
        fileEdits = [];
        editsByFile.set(loc.fileName, fileEdits);
      }
      fileEdits.push({ span: loc.textSpan, newText: newName });
    }

    const oldContents = new Map<string, string>();
    for (const [fileName, edits] of editsByFile) {
      if (!scope.contains(fileName)) {
        scope.recordSkipped(fileName);
        continue;
      }
      const original = this.readFile(fileName);
      oldContents.set(fileName, original);
      const updated = applyTextEdits(original, edits);
      scope.writeFile(fileName, updated);
      service.fileContents.set(fileName, updated);
    }

    const excludePositions = locs.map((loc) => ({
      file: loc.fileName,
      offset: loc.textSpan.start,
    }));
    const nameMatches = scanVueNameMatches(oldName, oldContents, excludePositions);

    return {
      filesModified: scope.modified,
      filesSkipped: scope.skipped,
      symbolName: oldName,
      newName,
      locationCount: locs.length,
      nameMatches,
    };
  }
}

src/daemon/dispatcher.ts.source:
import {
  DeleteFileArgsSchema,
  ExtractFunctionArgsSchema,
  FindImportersArgsSchema,
  FindReferencesArgsSchema,
  GetDefinitionArgsSchema,
  GetTypeErrorsArgsSchema,
  MoveArgsSchema,
  MoveDirectoryArgsSchema,
  MoveSymbolArgsSchema,
  RenameArgsSchema,
  ReplaceTextArgsSchema,
  SearchTextArgsSchema,
  SetExportArgsSchema,
} from "../adapters/schema.js";
import { EngineError, type ErrorCode } from "../domain/errors.js";
import { validateFilePath } from "../domain/security.js";
import { WorkspaceScope } from "../domain/workspace-scope.js";
import { extractFunction } from "../operations/extractFunction.js";
import { findImporters } from "../operations/findImporters.js";
import { findReferences } from "../operations/findReferences.js";
import { getDefinition } from "../operations/getDefinition.js";
import { getTypeErrors } from "../operations/getTypeErrors.js";
import { moveDirectory } from "../operations/moveDirectory.js";
import { moveFile } from "../operations/moveFile.js";
import { rename } from "../operations/rename.js";
import { replaceText } from "../operations/replaceText.js";
import { searchText } from "../operations/searchText.js";
import { setExport } from "../operations/setExport.js";
import type { EngineRegistry } from "../ts-engine/types.js";
import { resetDiscoveryCaches } from "../utils/ts-project.js";
import { makeRegistry } from "./language-plugin-registry.js";
import { getTypeErrorsForFiles } from "./post-write-diagnostics.js";
import { getSharedFileSystem } from "./self-write-state.js";

/**
 * Every dispatched operation shares this instance rather than constructing
 * its own, so a write one operation makes is visible — through the same
 * object — to every `WorkspaceScope` built for the requests that follow.
 * Mirrors the `defaultFs` precedent in `daemon.ts`.
 */
const defaultFs = getSharedFileSystem();

export { createVueLanguagePlugin } from "../plugins/vue/plugin.js";
export type { LanguagePlugin } from "../ts-engine/types.js";
export {
  clearLanguagePlugins,
  invalidateAll,
  invalidateFile,
  makeRegistry,
  registerLanguagePlugin,
} from "./language-plugin-registry.js";
export { shouldSuppressSelfWrite } from "./self-write-state.js";

// ─── Operation descriptor table ───────────────────────────────────────────

interface OperationDescriptor {
  /** Param keys that hold file paths requiring workspace validation. */
  pathParams: string[];
  /**
   * Name of a param that, when present, names a tsconfig directly rather than a file to
   * discover one from — engine selection must consult it as-is instead of walking up from
   * `pathParams[0]`. Only `getTypeErrors`'s `tsconfig` needs this today; it also must exist
   * (and not be a directory) before it's handed to engine selection, since that's a raw
   * filesystem read rather than a discovery walk that tolerates a miss.
   */
  tsConfigParam?: string;
  /** Zod schema used to validate incoming params at the socket boundary. */
  schema: {
    safeParse(
      data: unknown,
    ):
      | { success: true; data: Record<string, unknown> }
      | { success: false; error: { issues: Array<{ message: string }> } };
  };
  /** Call the appropriate compiler method and return the raw result. */
  invoke(
    registry: EngineRegistry,
    params: Record<string, unknown>,
    workspace: string,
  ): Promise<unknown>;
}

const OPERATIONS: Record<string, OperationDescriptor> = {
  rename: {
    pathParams: ["file"],
    schema: RenameArgsSchema,
    async invoke(registry, params, workspace) {
      const { file, line, col, newName } = params as {
        file: string;
        line: number;
        col: number;
        newName: string;
      };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, defaultFs);
      return rename(engine, file, line, col, newName, scope);
    },
  },

  moveFile: {
    pathParams: ["oldPath", "newPath"],
    schema: MoveArgsSchema,
    async invoke(registry, params, workspace) {
      const { oldPath, newPath } = params as { oldPath: string; newPath: string };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, defaultFs);
      return moveFile(engine, oldPath, newPath, scope);
    },
  },

  moveDirectory: {
    pathParams: ["oldPath", "newPath"],
    schema: MoveDirectoryArgsSchema,
    async invoke(registry, params, workspace) {
      const { oldPath, newPath } = params as { oldPath: string; newPath: string };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, defaultFs);
      return moveDirectory(engine, oldPath, newPath, scope);
    },
  },

  moveSymbol: {
    pathParams: ["sourceFile", "destFile"],
    schema: MoveSymbolArgsSchema,
    async invoke(registry, params, workspace) {
      const { sourceFile, symbolName, destFile, force } = params as {
        sourceFile: string;
        symbolName: string;
        destFile: string;
        force?: boolean;
      };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, defaultFs);
      const { moveSymbol } = await import("../operations/moveSymbol.js");
      return moveSymbol(engine, sourceFile, symbolName, destFile, scope, { force });
    },
  },

  extractFunction: {
    pathParams: ["file"],
    schema: ExtractFunctionArgsSchema,
    async invoke(registry, params, workspace) {
      const { file, startLine, startCol, endLine, endCol, functionName } = params as {
        file: string;
        startLine: number;
        startCol: number;
        endLine: number;
        endCol: number;
        functionName: string;
      };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, defaultFs);
      return extractFunction(
        engine,
        file,
        startLine,
        startCol,
        endLine,
        endCol,
        functionName,
        scope,
      );
    },
  },

  setExport: {
    pathParams: ["file"],
    schema: SetExportArgsSchema,
    async invoke(registry, params, workspace) {
      const { file, symbolName, exported } = params as {
        file: string;
        symbolName: string;
        exported: boolean;
      };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, defaultFs);
      return setExport(engine, file, symbolName, exported, scope);
    },
  },

  findImporters: {
    pathParams: ["file"],
    schema: FindImportersArgsSchema,
    async invoke(registry, params) {
      const { file } = params as { file: string };
      const engine = await registry.projectEngine();
      return findImporters(engine, file, defaultFs);
    },
  },

  findReferences: {
    pathParams: ["file"],
    schema: FindReferencesArgsSchema,
    async invoke(registry, params) {
      const { file, line, col } = params as { file: string; line: number; col: number };
      const engine = await registry.projectEngine();
      return findReferences(engine, file, line, col, defaultFs);
    },
  },

  getDefinition: {
    pathParams: ["file"],
    schema: GetDefinitionArgsSchema,
    async invoke(registry, params) {
      const { file, line, col } = params as { file: string; line: number; col: number };
      const engine = await registry.projectEngine();
      return getDefinition(engine, file, line, col, defaultFs);
    },
  },

  getTypeErrors: {
    pathParams: ["file", "tsconfig"],
    tsConfigParam: "tsconfig",
    schema: GetTypeErrorsArgsSchema,
    async invoke(registry, params, workspace) {
      const { file, tsconfig } = params as { file?: string; tsconfig?: string };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, defaultFs);
      return getTypeErrors(engine, file, scope, tsconfig);
    },
  },

  searchText: {
    pathParams: [],
    schema: SearchTextArgsSchema,
    async invoke(_registry, params, workspace) {
      const { pattern, glob, excludeGlob, context, maxResults } = params as {
        pattern: string;
        glob?: string;
        excludeGlob?: string;
        context?: number;
        maxResults?: number;
      };
      const scope = new WorkspaceScope(workspace, defaultFs);
      return searchText(pattern, scope, { glob, excludeGlob, context, maxResults });
    },
  },

  deleteFile: {
    pathParams: ["file"],
    schema: DeleteFileArgsSchema,
    async invoke(registry, params, workspace) {
      const { file } = params as { file: string };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, defaultFs);
      const { deleteFile } = await import("../operations/deleteFile.js");
      return deleteFile(engine, file, scope);
    },
  },

  replaceText: {
    pathParams: [],
    schema: ReplaceTextArgsSchema,
    async invoke(_registry, params, workspace) {
      const { pattern, replacement, glob, excludeGlob, edits } = params as {
        pattern?: string;
        replacement?: string;
        glob?: string;
        excludeGlob?: string;
        edits?: Array<{
          file: string;
          line: number;
          col: number;
          oldText: string;
          newText: string;
        }>;
      };
      const scope = new WorkspaceScope(workspace, defaultFs);
      return replaceText(scope, { pattern, replacement, glob, excludeGlob, edits });
    },
  },
};

/** Canonical list of dispatchable operation names — the single source of truth. */
export const OPERATION_NAMES: string[] = Object.keys(OPERATIONS);

/** The param keys a method declares as file paths; empty for methods with none. */
export function pathParamsFor(method: string): string[] {
  return OPERATIONS[method]?.pathParams ?? [];
}

// ─── Response types ────────────────────────────────────────────────────────

export type DispatchError = {
  status: "error";
  error: ErrorCode;
  message: string;
  /** Frame lines only, present exclusively on INTERNAL_ERROR. */
  stack?: string;
};

export type DispatchResponse =
  | ({ status: "success" | "warn" } & Record<string, unknown>)
  | DispatchError;

/**
 * Strip the workspace prefix from absolute paths in a stack trace so that
 * responses are portable and don't leak the full host path.
 *
 * `workspace` always arrives resolved (validateWorkspace runs path.resolve and
 * rejects "/"), so it never carries a trailing slash to normalise away.
 */
function stripWorkspacePrefix(stack: string, workspace: string): string {
  return stack.replaceAll(`${workspace}/`, "");
}

/** Frame lines only (drops the leading `Name: message` line), capped and workspace-stripped. */
function formatStack(stack: string, workspace: string): string {
  const frames = stack.split("\n").slice(1, 11);
  return stripWorkspacePrefix(frames.join("\n"), workspace);
}

function toDispatchError(err: unknown, method: string, workspace: string): DispatchError {
  if (EngineError.is(err)) {
    return { status: "error", error: err.code, message: err.message };
  }
  if (err instanceof Error) {
    return {
      status: "error",
      error: "INTERNAL_ERROR",
      message: `${err.name} during '${method}': ${err.message}`,
      ...(err.stack ? { stack: formatStack(err.stack, workspace) } : {}),
    };
  }
  return { status: "error", error: "INTERNAL_ERROR", message: String(err) };
}

// ─── Dispatcher ────────────────────────────────────────────────────────────

export async function dispatchRequest(
  req: { method: string; params: Record<string, unknown> },
  workspace: string,
): Promise<DispatchResponse> {
  try {
    // Fresh per dispatch so a tsconfig.json or the workspace's first .vue file added
    // since the last request is picked up before engine selection or project discovery.
    resetDiscoveryCaches();

    const descriptor = OPERATIONS[req.method];
    if (!descriptor) {
      return {
        status: "error" as const,
        error: "UNKNOWN_METHOD",
        message: `Unknown method: ${req.method}`,
      };
    }

    const parsed = descriptor.schema.safeParse(req.params);
    if (!parsed.success) {
      const message = parsed.error.issues.map((i) => i.message).join("; ");
      return { status: "error" as const, error: "VALIDATION_ERROR", message };
    }

    for (const paramKey of descriptor.pathParams) {
      const value = req.params[paramKey] as string | undefined;
      // Every current caller of this operation supplies every pathParam it declares, except
      // getTypeErrors's `file`/`tsconfig` — both optional, and mutually exclusive with each
      // other, so either (or neither) can be absent from a given request.
      if (value === undefined) continue;
      const pathResult = validateFilePath(value);
      if (!pathResult.ok) {
        return {
          status: "error" as const,
          error: "INVALID_PATH",
          message:
            pathResult.reason === "CONTROL_CHARS"
              ? `path contains control characters: ${paramKey}`
              : `path contains URI fragment or query character: ${paramKey}`,
        };
      }
      if (!new WorkspaceScope(workspace, defaultFs).contains(value)) {
        return {
          status: "error" as const,
          error: "WORKSPACE_VIOLATION",
          message: `${paramKey} is outside the workspace: ${value}`,
        };
      }
    }

    const explicitTsConfig =
      descriptor.tsConfigParam && typeof req.params[descriptor.tsConfigParam] === "string"
        ? (req.params[descriptor.tsConfigParam] as string)
        : undefined;

    if (explicitTsConfig !== undefined) {
      // Engine selection reads this path directly (isVueProject), unlike the discovery
      // routes above it doesn't tolerate a miss — checked here, before that read, so a
      // missing or directory tsconfig comes back as FILE_NOT_FOUND rather than whatever
      // ts-morph/TypeScript does when handed a path that isn't a file.
      if (!defaultFs.exists(explicitTsConfig) || defaultFs.stat(explicitTsConfig).isDirectory()) {
        return {
          status: "error" as const,
          error: "FILE_NOT_FOUND",
          message: `tsconfig not found: ${explicitTsConfig}`,
        };
      }
    }

    const registry =
      descriptor.pathParams.length > 0
        ? makeRegistry(req.params[descriptor.pathParams[0]] as string, workspace, explicitTsConfig)
        : makeRegistry(undefined, workspace, explicitTsConfig);

    const result = (await descriptor.invoke(registry, parsed.data, workspace)) as Record<
      string,
      unknown
    >;

    if (
      parsed.data.checkTypeErrors !== false &&
      Array.isArray(result.filesModified) &&
      (result.filesModified as string[]).length > 0
    ) {
      const engine = await registry.projectEngine();
      const diagnostics = await getTypeErrorsForFiles(
        engine,
        result.filesModified as string[],
        new WorkspaceScope(workspace, defaultFs),
      );
      result.typeErrors = diagnostics.typeErrors;
      result.typeErrorCount = diagnostics.typeErrorCount;
      result.typeErrorsTruncated = diagnostics.typeErrorsTruncated;
    }

    const status =
      typeof result.typeErrorCount === "number" && result.typeErrorCount > 0
        ? ("warn" as const)
        : ("success" as const);
    return { status, ...result };
  } catch (err) {
    return toDispatchError(err, req.method, workspace);
  }
}

