import safeRegex from "safe-regex2";
import { EngineError } from "../domain/errors.js";
import { isSensitiveFile } from "../domain/security.js";
import type { WorkspaceScope } from "../domain/workspace-scope.js";
import { walkWorkspaceFiles } from "../utils/file-walk.js";
import type { SearchMatch, SearchTextResult } from "./types.js";

const DEFAULT_MAX_RESULTS = 500;

/** Return true if the string content appears to be binary (contains a null character). */
function isBinaryContent(content: string): boolean {
  const checkLen = Math.min(content.length, 512);
  for (let i = 0; i < checkLen; i++) {
    if (content.charCodeAt(i) === 0) return true;
  }
  return false;
}

/**
 * Search for a regex pattern across all text files in the workspace.
 *
 * @param pattern - ECMAScript regex pattern string
 * @param scope - workspace scope used to resolve the root and read file content
 * @param opts.glob - optional glob to restrict which files are searched
 * @param opts.excludeGlob - optional glob of files to exclude, applied after `glob`
 * @param opts.context - lines of context before and after each match (like grep -C)
 * @param opts.maxResults - cap on total matches returned (default 500)
 */
export async function searchText(
  pattern: string,
  scope: WorkspaceScope,
  opts: { glob?: string; excludeGlob?: string; context?: number; maxResults?: number } = {},
): Promise<SearchTextResult> {
  const { glob, excludeGlob, context = 0, maxResults = DEFAULT_MAX_RESULTS } = opts;

  let re: RegExp;
  try {
    re = new RegExp(pattern, "g");
  } catch {
    throw new EngineError(`Invalid regex pattern: ${pattern}`, "PARSE_ERROR");
  }
  if (!safeRegex(re)) {
    throw new EngineError(
      `Pattern rejected: potential ReDoS (catastrophic backtracking): ${pattern}`,
      "REDOS",
    );
  }

  const files = walkWorkspaceFiles(scope.root, { glob, excludeGlob, fs: scope.fs });
  const matches: SearchMatch[] = [];
  let truncated = false;

  outer: for (const filePath of files) {
    if (isSensitiveFile(filePath)) continue;

    let content: string;
    try {
      content = scope.fs.readFile(filePath);
    } catch {
      scope.recordSkipped(filePath);
      continue;
    }
    if (isBinaryContent(content)) continue;

    // Split into lines; trim the trailing empty string that results from a
    // final newline (virtually all text files end with one).
    const rawLines = content.split("\n");
    const lines =
      rawLines.length > 0 && rawLines[rawLines.length - 1] === ""
        ? rawLines.slice(0, -1)
        : rawLines;

    for (let lineIdx = 0; lineIdx < lines.length; lineIdx++) {
      const lineText = lines[lineIdx];
      // Reset lastIndex for each line (the regex has the `g` flag)
      re.lastIndex = 0;
      let m: RegExpExecArray | null;
      // biome-ignore lint/suspicious/noAssignInExpressions: standard regex loop idiom
      while ((m = re.exec(lineText)) !== null) {
        const lineNum = lineIdx + 1; // 1-based
        const colNum = m.index + 1; // 1-based

        const match: SearchMatch = {
          file: filePath,
          line: lineNum,
          col: colNum,
          matchText: m[0],
        };

        if (context > 0) {
          const start = Math.max(0, lineIdx - context);
          const end = Math.min(lines.length - 1, lineIdx + context);
          match.surroundingText = lines.slice(start, end + 1).join("\n");
        }

        matches.push(match);

        if (matches.length >= maxResults) {
          truncated = true;
          break outer;
        }

        // Prevent infinite loop on zero-length matches
        if (m[0].length === 0) re.lastIndex++;
      }
    }
  }

  return { matches, truncated };
}

src/utils/file-walk.ts.source:
import { spawnSync } from "node:child_process";
import * as path from "node:path";
import type { DirEntry, FileSystem } from "../ports/filesystem.js";
import { NodeFileSystem } from "../ports/node-filesystem.js";
import { compileGlob } from "./globs.js";

/**
 * Directories that are never meaningful to an agent when walking or watching
 * a workspace. Used by the file walker and the filesystem watcher.
 */
export const SKIP_DIRS = new Set(["node_modules", ".git", "dist", ".nuxt", ".output", ".vite"]);

/**
 * Filesystem reads go through the injected `FileSystem` port so the operations
 * core is testable in memory. Adapters (`ts-engine/`, `plugins/vue/`) that
 * legitimately touch real disk rely on this production default.
 */
const defaultFs = new NodeFileSystem();

/**
 * Collect all files under `dir` whose extension is in `extensions`.
 *
 * Strategy:
 * - If `dir` is inside a git repository, delegate to
 *   `git ls-files --cached --others --exclude-standard`. This respects
 *   .gitignore, nested .gitignore, and .git/info/exclude by construction and
 *   requires no skip-list maintenance.
 * - Otherwise (non-git workspace), fall back to a recursive readdir walk that
 *   skips SKIP_DIRS.
 */
export function walkFiles(dir: string, extensions: string[], fs: FileSystem = defaultFs): string[] {
  const extSet = new Set(extensions);

  const result = spawnSync("git", ["ls-files", "--cached", "--others", "--exclude-standard"], {
    cwd: dir,
    encoding: "utf8",
  });

  if (result.status === 0) {
    return result.stdout
      .split("\n")
      .filter(Boolean)
      .filter((line) => extSet.has(path.extname(line)))
      .map((line) => path.join(dir, line))
      .filter((abs) => fs.exists(abs));
  }

  // Fallback for non-git workspaces
  return walkRecursive(dir, fs).filter((f) => extSet.has(path.extname(f)));
}

/**
 * Enumerate all text files in the workspace, optionally filtered by a glob
 * and/or an exclude glob. Uses `git ls-files` when available (respects
 * .gitignore); falls back to a recursive readdir that skips SKIP_DIRS.
 *
 * `excludeGlob` is applied after `glob` — a file must match `glob` (if given)
 * and must not match `excludeGlob` (if given) to be returned.
 */
export function walkWorkspaceFiles(
  workspace: string,
  opts: { glob?: string; excludeGlob?: string; fs?: FileSystem } = {},
): string[] {
  const { glob, excludeGlob, fs = defaultFs } = opts;
  const globPred = glob ? compileGlob(glob) : null;
  const excludePred = excludeGlob ? compileGlob(excludeGlob) : null;

  const result = spawnSync("git", ["ls-files", "--cached", "--others", "--exclude-standard"], {
    cwd: workspace,
    encoding: "utf8",
  });

  let files: string[];
  if (result.status === 0) {
    files = result.stdout
      .split("\n")
      .filter(Boolean)
      .map((line) => path.join(workspace, line));
  } else {
    files = walkRecursive(workspace, fs);
  }

  if (globPred || excludePred) {
    files = files.filter((f) => {
      const rel = path.relative(workspace, f).split(path.sep).join("/");
      if (globPred && !globPred(rel)) return false;
      if (excludePred?.(rel)) return false;
      return true;
    });
  }

  return files;
}

/**
 * Recursively enumerate all files under `dir`, skipping SKIP_DIRS.
 * Returns all files without any extension or glob filtering.
 */
export function walkRecursive(dir: string, fs: FileSystem = defaultFs): string[] {
  const results: string[] = [];
  let entries: DirEntry[];
  try {
    entries = fs.readdir(dir);
  } catch {
    return results;
  }
  for (const entry of entries) {
    if (SKIP_DIRS.has(entry.name)) continue;
    const full = path.join(dir, entry.name);
    // isDirectory/isFile do not follow symlinks, so a symlink is neither and is
    // skipped — never recursed into, which would risk cycling through its target.
    if (entry.isDirectory()) {
      results.push(...walkRecursive(full, fs));
    } else if (entry.isFile()) {
      results.push(full);
    }
  }
  return results;
}

src/operations/findImporters.ts.source:
import * as path from "node:path";
import type { FileSystem } from "../ports/filesystem.js";
import type { Engine } from "../ts-engine/types.js";
import { assertFileExists } from "../utils/assert-file.js";
import { offsetToLineCol } from "../utils/text-utils.js";
import type { FindImportersResult } from "./types.js";

export async function findImporters(
  compiler: Engine,
  filePath: string,
  fs: FileSystem,
): Promise<FindImportersResult> {
  const absPath = assertFileExists(filePath, fs);

  const refs = await compiler.getFileReferences(absPath);
  const fileName = path.basename(absPath);

  if (!refs || refs.length === 0) {
    return { fileName, references: [] };
  }

  const references = refs.map((ref) => {
    const content = compiler.readFile(ref.fileName);
    const lc = offsetToLineCol(content, ref.textSpan.start);
    return { file: ref.fileName, line: lc.line, col: lc.col, length: ref.textSpan.length };
  });

  return { fileName, references };
}

src/ports/node-filesystem.ts.source:
import * as nodeFs from "node:fs";
import * as nodePath from "node:path";
import type { DirEntry, FileSystem } from "./filesystem.js";

/**
 * Production implementation that delegates to `node:fs` synchronous methods
 * and `node:path` for path resolution.
 *
 * Intended to be constructed once at daemon startup and shared across all
 * operations via `WorkspaceScope`.
 */
export class NodeFileSystem implements FileSystem {
  readFile(path: string): string {
    return nodeFs.readFileSync(path, "utf8");
  }

  writeFile(path: string, content: string): void {
    nodeFs.writeFileSync(path, content, "utf8");
  }

  exists(path: string): boolean {
    return nodeFs.existsSync(path);
  }

  mkdir(path: string, options?: { recursive?: boolean }): void {
    nodeFs.mkdirSync(path, options);
  }

  rename(oldPath: string, newPath: string): void {
    nodeFs.renameSync(oldPath, newPath);
  }

  unlink(path: string): void {
    nodeFs.unlinkSync(path);
  }

  realpath(path: string): string {
    return nodeFs.realpathSync(path);
  }

  resolve(...segments: string[]): string {
    return nodePath.resolve(...segments);
  }

  stat(path: string): { isDirectory(): boolean; mtimeMs: number } {
    return nodeFs.statSync(path);
  }

  readdir(path: string): DirEntry[] {
    return nodeFs.readdirSync(path, { withFileTypes: true });
  }
}

src/operations/getDefinition.ts.source:
import { EngineError } from "../domain/errors.js";
import type { FileSystem } from "../ports/filesystem.js";
import type { Engine } from "../ts-engine/types.js";
import { assertFileExists } from "../utils/assert-file.js";
import { offsetToLineCol } from "../utils/text-utils.js";
import type { GetDefinitionResult } from "./types.js";

export async function getDefinition(
  compiler: Engine,
  filePath: string,
  line: number,
  col: number,
  fs: FileSystem,
): Promise<GetDefinitionResult> {
  const absPath = assertFileExists(filePath, fs);

  const offset = compiler.resolveOffset(absPath, line, col);
  const defs = await compiler.getDefinitionAtPosition(absPath, offset);

  if (!defs || defs.length === 0) {
    throw new EngineError(
      `No symbol at line ${line}, col ${col} in ${filePath}`,
      "SYMBOL_NOT_FOUND",
    );
  }

  const symbolName = defs[0].name;

  const definitions = defs.map((def) => {
    const content = compiler.readFile(def.fileName);
    const lc = offsetToLineCol(content, def.textSpan.start);
    return { file: def.fileName, line: lc.line, col: lc.col, length: def.textSpan.length };
  });

  return { symbolName, definitions };
}

src/operations/findReferences.ts.source:
import { EngineError } from "../domain/errors.js";
import type { FileSystem } from "../ports/filesystem.js";
import type { Engine } from "../ts-engine/types.js";
import { assertFileExists } from "../utils/assert-file.js";
import { offsetToLineCol } from "../utils/text-utils.js";
import type { FindReferencesResult } from "./types.js";

export async function findReferences(
  compiler: Engine,
  filePath: string,
  line: number,
  col: number,
  fs: FileSystem,
): Promise<FindReferencesResult> {
  const absPath = assertFileExists(filePath, fs);

  const offset = compiler.resolveOffset(absPath, line, col);
  const refs = await compiler.getReferencesAtPosition(absPath, offset);

  if (!refs || refs.length === 0) {
    throw new EngineError(
      `No symbol at line ${line}, col ${col} in ${filePath}`,
      "SYMBOL_NOT_FOUND",
    );
  }

  const firstRef = refs[0];
  const firstContent = compiler.readFile(firstRef.fileName);
  const symbolName = firstContent.slice(
    firstRef.textSpan.start,
    firstRef.textSpan.start + firstRef.textSpan.length,
  );

  const references = refs.map((ref) => {
    const content = compiler.readFile(ref.fileName);
    const lc = offsetToLineCol(content, ref.textSpan.start);
    return { file: ref.fileName, line: lc.line, col: lc.col, length: ref.textSpan.length };
  });

  return { symbolName, references };
}

src/operations/moveDirectory.ts.source:
import * as path from "node:path";
import { EngineError } from "../domain/errors.js";
import type { WorkspaceScope } from "../domain/workspace-scope.js";
import type { FileSystem } from "../ports/filesystem.js";
import type { Engine } from "../ts-engine/types.js";
import type { MoveDirectoryResult } from "./types.js";

function isNonEmptyDir(absPath: string, fs: FileSystem): boolean {
  // readdir throws for a missing path or a file — both mean "not a non-empty dir".
  try {
    return fs.readdir(absPath).length > 0;
  } catch {
    return false;
  }
}

export async function moveDirectory(
  compiler: Engine,
  oldPath: string,
  newPath: string,
  scope: WorkspaceScope,
): Promise<MoveDirectoryResult> {
  const absOld = path.resolve(oldPath);
  const absNew = path.resolve(newPath);

  if (!scope.fs.exists(absOld)) {
    throw new EngineError(`Directory not found: ${absOld}`, "FILE_NOT_FOUND");
  }
  if (!scope.fs.stat(absOld).isDirectory()) {
    throw new EngineError(`Path is not a directory: ${absOld}`, "NOT_A_DIRECTORY");
  }

  const rel = path.relative(absOld, absNew);
  if (!rel.startsWith("..")) {
    throw new EngineError(`Cannot move a directory into itself: ${absNew}`, "MOVE_INTO_SELF");
  }

  if (isNonEmptyDir(absNew, scope.fs)) {
    throw new EngineError(
      `Destination already exists and is non-empty: ${absNew}`,
      "DESTINATION_EXISTS",
    );
  }

  const { filesMoved } = await compiler.moveDirectory(absOld, absNew, scope);

  return {
    filesMoved,
    filesModified: scope.modified,
    filesSkipped: scope.skipped,
    oldPath: absOld,
    newPath: absNew,
  };
}

src/daemon/lifecycle.ts.source:
import type { FileSystem } from "../ports/filesystem.js";

export interface DaemonHost {
  onSignal(signal: "SIGTERM" | "SIGINT", handler: () => void): void;
  exit(code: number): void;
}

export interface DaemonServer {
  listen(path: string): void;
  close(): void;
}

export interface DaemonWatcher {
  stop(): Promise<void>;
}

export interface DaemonLifecycleOpts {
  sockPath: string;
  pidPath: string;
  pid: number;
  fs: FileSystem;
  host: DaemonHost;
  startServer: () => DaemonServer;
  startWatcher: () => DaemonWatcher;
  signalReady: () => void;
  logger?: { cleanup(): void };
}

export async function runLifecycle(opts: DaemonLifecycleOpts): Promise<void> {
  const { sockPath, pidPath, pid, fs, host, startServer, startWatcher, signalReady, logger } = opts;

  let server: DaemonServer | undefined;
  let watcher: DaemonWatcher | undefined;

  function shutdown(): void {
    void watcher?.stop();
    server?.close();
    logger?.cleanup();
    try {
      fs.unlink(sockPath);
    } catch {
      // already gone
    }
    try {
      fs.unlink(pidPath);
    } catch {
      // already gone
    }
    host.exit(0);
  }

  // Handlers are installed before the daemon becomes discoverable so no signal
  // can arrive after the lockfile is written but before cleanup is registered.
  host.onSignal("SIGTERM", shutdown);
  host.onSignal("SIGINT", shutdown);

  fs.writeFile(pidPath, JSON.stringify({ pid, startedAt: Date.now() }));

  server = startServer();
  server.listen(sockPath);

  watcher = startWatcher();

  signalReady();
}

src/domain/workspace-scope.ts.source:
import type { FileSystem } from "../ports/filesystem.js";
import { EngineError } from "./errors.js";
import { isWithinWorkspace } from "./security.js";

/**
 * Tracks workspace boundary membership and records which files were modified
 * or skipped during an operation.
 *
 * `contains()` resolves symlinks via `this.fs` before calling the pure
 * `isWithinWorkspace` — callers must not reimplement the boundary check.
 *
 * `writeFile()` enforces the boundary before writing: paths outside the workspace
 * throw `EngineError` with code `"WORKSPACE_VIOLATION"`.
 */
export class WorkspaceScope {
  readonly fs: FileSystem;
  readonly root: string;
  private readonly _modified = new Set<string>();
  private readonly _skipped = new Set<string>();

  constructor(root: string, fs: FileSystem) {
    this.root = root;
    this.fs = fs;
  }

  contains(filePath: string): boolean {
    if (!isWithinWorkspace(filePath, this.root)) return false;
    if (this.fs.exists(filePath)) {
      try {
        const realFile = this.fs.realpath(filePath);
        const realRoot = this.fs.realpath(this.root);
        return isWithinWorkspace(realFile, realRoot);
      } catch {
        return false;
      }
    }
    return true;
  }

  recordModified(filePath: string): void {
    this._modified.add(filePath);
  }

  recordSkipped(filePath: string): void {
    this._skipped.add(filePath);
  }

  writeFile(filePath: string, content: string): void {
    if (!this.contains(filePath)) {
      throw new EngineError(
        `Path is outside the workspace boundary: ${filePath}`,
        "WORKSPACE_VIOLATION",
      );
    }
    this.fs.writeFile(filePath, content);
    this.recordModified(filePath);
  }

  /** Returns a new array on every call — snapshot before looping if you check membership repeatedly. */
  get modified(): string[] {
    return [...this._modified];
  }

  get skipped(): string[] {
    return [...this._skipped];
  }
}

