    test("project-wide: still reports TS2307 when the SFC does not exist", async ({
      seedInlineFixture,
    }) => {
      const dir = await seedInlineFixture({
        "tsconfig.json": JSON.stringify({
          compilerOptions: {
            strict: true,
            target: "ESNext",
