import * as fs from "node:fs";
import * as path from "node:path";
import { describe, expect } from "vitest";
import { FIXTURES, fileExists, readFile, fixtureTest as test } from "../__testHelpers__/helpers.js";
import { WorkspaceScope } from "../domain/workspace-scope.js";
import { NodeFileSystem } from "../ports/node-filesystem.js";
import { TsMorphEngine } from "./engine.js";
import { tsMoveSymbol } from "./move-symbol.js";

const TSCONFIG = JSON.stringify({ compilerOptions: { strict: true }, include: ["**/*.ts"] });

function makeScope(root: string): WorkspaceScope {
  return new WorkspaceScope(root, new NodeFileSystem());
}

describe("tsMoveSymbol", () => {
  describe("symbol move to new file", () => {
    test("moves a named export to a new file and saves both files", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const tsCompiler = new TsMorphEngine();
      const scope = makeScope(dir);
      const srcPath = path.join(dir, "src/utils.ts");
      const dstPath = path.join(dir, "src/helpers.ts");

      await tsMoveSymbol(tsCompiler, srcPath, "greetUser", dstPath, scope);

      expect(readFile(dir, "src/helpers.ts")).toContain("export function greetUser");
      expect(readFile(dir, "src/utils.ts")).not.toContain("greetUser");
      expect(scope.modified).toContain(srcPath);
      expect(scope.modified).toContain(dstPath);
    });

    test("updates the import in the importing file with .js extension", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      await tsMoveSymbol(
        new TsMorphEngine(),
        path.join(dir, "src/utils.ts"),
        "greetUser",
        path.join(dir, "src/helpers.ts"),
        makeScope(dir),
      );

      const mainContent = readFile(dir, "src/main.ts");
      expect(mainContent).toContain('"./helpers.js"');
      expect(mainContent).not.toContain('"./utils"');
    });
  });

  describe("symbol move to existing file", () => {
    test("moves a function to an existing file, preserving existing content", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      fs.writeFileSync(
        path.join(dir, "src/helpers.ts"),
        'export function helper(): string { return "hi"; }\n',
      );
      await tsMoveSymbol(
        new TsMorphEngine(),
        path.join(dir, "src/utils.ts"),
        "greetUser",
        path.join(dir, "src/helpers.ts"),
        makeScope(dir),
      );
      const destContent = readFile(dir, "src/helpers.ts");
      expect(destContent).toContain("helper");
      expect(destContent).toContain("greetUser");
    });

    test("appends to a non-empty destination file with a blank-line separator", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      fs.writeFileSync(
        path.join(dir, "src/helpers.ts"),
        'export function helper(): string { return "hi"; }\n',
      );
      await tsMoveSymbol(
        new TsMorphEngine(),
        path.join(dir, "src/utils.ts"),
        "greetUser",
        path.join(dir, "src/helpers.ts"),
        makeScope(dir),
      );
      const content = readFile(dir, "src/helpers.ts");
      expect(content).toMatch(/helper[\s\S]*\n\nexport function greetUser/);
      expect(content.startsWith("export function helper")).toBe(true);
    });
  });

  describe("boundary skipping", () => {
    test("records importer outside the workspace boundary as skipped, not modified", async ({
      seedInlineFixture,
    }) => {
      const dir = await seedInlineFixture({
        "tsconfig.json": TSCONFIG,
        "src/utils.ts": "export function add(a: number, b: number): number { return a + b; }\n",
        "lib/consumer.ts": 'import { add } from "../src/utils";\nexport const r = add(1, 2);\n',
      });
      const scope = makeScope(path.join(dir, "src"));
      const p = new TsMorphEngine();

      await tsMoveSymbol(
        p,
        path.join(dir, "src/utils.ts"),
        "add",
        path.join(dir, "src/helpers.ts"),
        scope,
      );

      expect(scope.skipped.some((f) => f.includes("consumer.ts"))).toBe(true);
      expect(scope.modified.some((f) => f.includes("consumer.ts"))).toBe(false);
      expect(readFile(dir, "lib/consumer.ts")).toContain("../src/utils");
    });

    test("skipped includes dirty source file outside the workspace root", async ({
      seedInlineFixture,
    }) => {
      const dir = await seedInlineFixture({
        "tsconfig.json": TSCONFIG,
        "lib/utils.ts": "export function add(a: number, b: number): number { return a + b; }\n",
      });
      const scope = makeScope(path.join(dir, "src"));
      const p = new TsMorphEngine();

      await tsMoveSymbol(
        p,
        path.join(dir, "lib/utils.ts"),
        "add",
        path.join(dir, "src/helpers.ts"),
        scope,
      );

      expect(scope.skipped.some((f) => f.includes("lib/utils.ts"))).toBe(true);
      expect(scope.modified.some((f) => f.includes("src/helpers.ts"))).toBe(true);
      expect(readFile(dir, "lib/utils.ts")).toContain("add");
    });
  });

  describe("directory creation", () => {
    test("creates the destination directory when it does not exist", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const dstPath = path.join(dir, "src/nested/deep/helpers.ts");

      await tsMoveSymbol(
        new TsMorphEngine(),
        path.join(dir, "src/utils.ts"),
        "greetUser",
        dstPath,
        makeScope(dir),
      );

      expect(fileExists(dir, "src/nested/deep/helpers.ts")).toBe(true);
      expect(readFile(dir, "src/nested/deep/helpers.ts")).toContain("greetUser");
    });
  });

  describe("const variable move", () => {
    test("moves an exported const variable (VariableDeclaration to VariableStatement traversal)", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const scope = makeScope(dir);
      fs.appendFileSync(path.join(dir, "src/utils.ts"), "\nexport const VERSION = '1.0.0';\n");
      fs.writeFileSync(
        path.join(dir, "src/consumer.ts"),
        'import { VERSION } from "./utils";\nexport const v = VERSION;\n',
      );
      await tsMoveSymbol(
        new TsMorphEngine(),
        path.join(dir, "src/utils.ts"),
        "VERSION",
        path.join(dir, "src/constants.ts"),
        scope,
      );
      expect(readFile(dir, "src/constants.ts")).toContain("export const VERSION");
      expect(readFile(dir, "src/utils.ts")).not.toContain("VERSION");
      expect(readFile(dir, "src/consumer.ts")).toContain('"./constants.js"');
      expect(scope.modified).toContain(path.join(dir, "src/consumer.ts"));
    });
  });

  describe("dest file self-import removal", () => {
    test("does not add a self-import in dest file when dest already had a self-referencing import from source", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const scope = makeScope(dir);
      fs.writeFileSync(
        path.join(dir, "src/helpers.ts"),
        'import { greetUser } from "./utils";\nexport function helper(): void { greetUser("x"); }\n',
      );
      await tsMoveSymbol(
        new TsMorphEngine(),
        path.join(dir, "src/utils.ts"),
        "greetUser",
        path.join(dir, "src/helpers.ts"),
        scope,
      );
      const helperContent = readFile(dir, "src/helpers.ts");
      expect(helperContent).not.toContain('"./helpers.js"');
      expect(helperContent).toContain("export function greetUser");
    });
  });

  describe("does not add unrelated saved files to modified", () => {
    test("only records files actually changed by the move", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const scope = makeScope(dir);
      const extraPath = path.join(dir, "src/unrelated.ts");
      fs.writeFileSync(extraPath, "export const UNRELATED = 42;\n");

      await tsMoveSymbol(
        new TsMorphEngine(),
        path.join(dir, "src/utils.ts"),
        "greetUser",
        path.join(dir, "src/helpers.ts"),
        scope,
      );

      expect(scope.modified).not.toContain(extraPath);
    });
  });

  describe("source self-import after move", () => {
    test("adds an import back to source when remaining code references the moved symbol", async ({
      seedInlineFixture,
    }) => {
      const dir = await seedInlineFixture({
        "tsconfig.json": TSCONFIG,
        "src/a.ts":
          "export function Foo(): string { return 'foo'; }\nexport function Bar(): string { return Foo(); }\n",
        "src/dest.ts": "",
      });
      const srcPath = path.join(dir, "src/a.ts");
      const dstPath = path.join(dir, "src/dest.ts");
      const scope = makeScope(dir);

      await tsMoveSymbol(new TsMorphEngine(), srcPath, "Foo", dstPath, scope);

      const srcContent = readFile(dir, "src/a.ts");
      expect(srcContent).toContain("import { Foo }");
      expect(srcContent).toContain('"./dest.js"');
      expect(srcContent).toContain("export function Bar");
      expect(srcContent).not.toContain("export function Foo");
      expect(scope.modified).toContain(srcPath);
    });

    test("keeps a byte-order mark at the start of the file when prepending that import", async ({
      seedInlineFixture,
    }) => {
      const dir = await seedInlineFixture({
        "tsconfig.json": TSCONFIG,
        "src/a.ts":
          "﻿export function Foo(): string { return 'foo'; }\nexport function Bar(): string { return Foo(); }\n",
        "src/dest.ts": "",
      });
      const srcPath = path.join(dir, "src/a.ts");
      const scope = makeScope(dir);

      await tsMoveSymbol(new TsMorphEngine(), srcPath, "Foo", path.join(dir, "src/dest.ts"), scope);

      // Asserted on bytes: a string comparison passes whether the mark sits at
      // byte 0 or has been pushed behind the new import line, and a mark that
      // has drifted off byte 0 is a stray character rather than an encoding hint.
      const bytes = fs.readFileSync(srcPath);
      expect(bytes.subarray(0, 3)).toEqual(Buffer.from([0xef, 0xbb, 0xbf]));
      expect(bytes.indexOf(Buffer.from([0xef, 0xbb, 0xbf]), 1)).toBe(-1);
    });
  });

  describe("transitive import carry", () => {
    test("carries a named import the moved declaration depends on to the destination", async ({
      seedInlineFixture,
    }) => {
      const dir = await seedInlineFixture({
        "tsconfig.json": TSCONFIG,
        "src/types.ts": "export type Bar = { value: string };\n",
        "src/source.ts":
          'import { Bar } from "./types";\nexport function Foo(b: Bar): string { return b.value; }\n',
        "src/dest.ts": "",
      });
      const scope = makeScope(dir);

      await tsMoveSymbol(
        new TsMorphEngine(),
        path.join(dir, "src/source.ts"),
        "Foo",
        path.join(dir, "src/dest.ts"),
        scope,
      );

      const destContent = readFile(dir, "src/dest.ts");
      expect(destContent).toContain("import { Bar }");
      expect(destContent).toContain('"./types.js"');
      expect(destContent).toContain("export function Foo");
    });
  });

  describe("non-exported conflict detection", () => {
    test("throws SYMBOL_EXISTS when destination has a non-exported declaration with the same name", async ({
      seedInlineFixture,
    }) => {
      const dir = await seedInlineFixture({
        "tsconfig.json": TSCONFIG,
        "src/source.ts": "export function Foo(): void {}\n",
        "src/dest.ts": "function Foo(): void {}\nexport function other(): void {}\n",
      });
      const scope = makeScope(dir);

      await expect(
        tsMoveSymbol(
          new TsMorphEngine(),
          path.join(dir, "src/source.ts"),
          "Foo",
          path.join(dir, "src/dest.ts"),
          scope,
        ),
      ).rejects.toMatchObject({ code: "SYMBOL_EXISTS" });
    });

    test("replaces the non-exported declaration when force is true", async ({
      seedInlineFixture,
    }) => {
      const dir = await seedInlineFixture({
        "tsconfig.json": TSCONFIG,
        "src/source.ts": "export function Foo(): string { return 'new'; }\n",
        "src/dest.ts":
          "function Foo(): string { return 'old'; }\nexport function other(): void {}\n",
      });
      const scope = makeScope(dir);

      await tsMoveSymbol(
        new TsMorphEngine(),
        path.join(dir, "src/source.ts"),
        "Foo",
        path.join(dir, "src/dest.ts"),
        scope,
        { force: true },
      );

      const destContent = readFile(dir, "src/dest.ts");
      expect(destContent).toContain("export function Foo");
      expect(destContent).toContain("return 'new'");
      expect(destContent).not.toContain("return 'old'");
      const fooMatches = destContent.match(/function Foo/g) ?? [];
      expect(fooMatches).toHaveLength(1);
    });
  });
});

src/__testHelpers__/scenarios/scenario-r.source:
import { describe, expect, it } from "vitest";
import { fixtureTest as test } from "../helpers.js";
import {
  assertEffects,
  assertResponseMatches,
  assertStepSucceeded,
  describeFailure,
  type Tree,
} from "./scenario-oracle.js";
import { executeScenario } from "./scenario-runner.js";
import type { Effects, Scenario, ScenarioFile } from "./scenario-schema.js";

/**
 * The scenario harness is a shared oracle: if its comparison is wrong, every scenario can
 * pass for the wrong reason. Its assertions are pure functions of the values they judge,
 * so most cases state one wrong contract about a known workspace change and watch the
 * oracle reject it — no project, no dispatch.
 */

/**
 * The workspace the cases judge: src/utils.ts imported once from src/main.ts, with a
 * tsconfig beside them.
 */
const BEFORE: Tree = {
  "tsconfig.json": `{ "compilerOptions": { "strict": true }, "include": ["src/**/*.ts"] }
`,
  "src/main.ts": `import { greetUser } from "./utils";

console.log(greetUser("World"));
`,
  "src/utils.ts": `export function greetUser(name: string): string {
  return \`Hello, \${name}\`;
}
`,
};

/** What moving src/utils.ts to lib/utils.ts leaves behind, the importer rewritten. */
const AFTER: Tree = {
  "tsconfig.json": BEFORE["tsconfig.json"],
  "lib/utils.ts": BEFORE["src/utils.ts"],
  "src/main.ts": `import { greetUser } from "../lib/utils";

console.log(greetUser("World"));
`,
};

/** The effect contract that move really performs: the move, the rewrite, the bystander. */
const CLEAN_EFFECTS: Effects = {
  moved: { "src/utils.ts": { to: "lib/utils.ts" } },
  changed: { "src/main.ts": AFTER["src/main.ts"] },
  unchanged: ["tsconfig.json"],
};

/** The response the dispatcher really returns for that move, in the sugar form files write. */
const WRITTEN_RESPONSE: Record<string, unknown> = {
  status: "success",
  typeErrors: "none",
  filesModified: ["src/main.ts", "lib/utils.ts"],
  filesSkipped: [],
  oldPath: "src/utils.ts",
  newPath: "lib/utils.ts",
};

/** The same response already scrubbed of the temp root, as the executor passes it in. */
const SCRUBBED_RESPONSE = {
  status: "success",
  typeErrors: [],
  typeErrorCount: 0,
  typeErrorsTruncated: false,
  filesModified: ["src/main.ts", "lib/utils.ts"],
  filesSkipped: [],
  oldPath: "src/utils.ts",
  newPath: "lib/utils.ts",
};

function effectsOf(parts: Partial<Effects> = {}): Effects {
  return { moved: {}, changed: {}, unchanged: [], ...parts };
}

function failureOf(assert: () => void): string {
  try {
    assert();
  } catch (err) {
    return (err as Error).message;
  }
  throw new Error("the oracle accepted a contract it should have rejected");
}

describe("effect contract", () => {
  it("passes when every declared effect holds and no unnamed file differs", () => {
    assertEffects(BEFORE, AFTER, CLEAN_EFFECTS);
  });

  it("accepts a move whose declared content is what landed", () => {
    const rewritten = "rewritten on the way\n";

    assertEffects(
      BEFORE,
      { ...AFTER, "lib/utils.ts": rewritten },
      {
        ...CLEAN_EFFECTS,
        moved: { "src/utils.ts": { to: "lib/utils.ts", content: rewritten } },
      },
    );
  });

  it("passes on an empty workspace with nothing declared", () => {
    assertEffects({}, {}, effectsOf());
  });

  it("rejects any effect against an empty workspace", () => {
    const message = failureOf(() =>
      assertEffects({}, {}, effectsOf({ moved: { "a.ts": { to: "b.ts" } } })),
    );

    expect(message).toContain("a.ts should have existed beforehand");
  });

  it("rejects a modification no `then.files` entry claims", () => {
    const message = failureOf(() =>
      assertEffects(
        BEFORE,
        AFTER,
        effectsOf({ moved: { "src/utils.ts": { to: "lib/utils.ts" } } }),
      ),
    );

    expect(message).toContain("files changed without being named in `then.files`");
    expect(message).toContain("src/main.ts");
  });

  it("rejects a claim that nothing happened at all", () => {
    const message = failureOf(() => assertEffects(BEFORE, AFTER, effectsOf()));

    // The destination did not exist before and the source is gone after, so a claim of
    // no effects has to fail on both.
    expect(message).toContain("files changed without being named in `then.files`");
    expect(message).toContain("lib/utils.ts");
  });

  it("rejects `changed` content that does not match the file on disk", () => {
    const message = failureOf(() =>
      assertEffects(BEFORE, AFTER, {
        ...CLEAN_EFFECTS,
        changed: { "src/main.ts": 'import { greetUser } from "./stale-path";\n' },
      }),
    );

    expect(message).toContain("src/main.ts content");
  });

  it("rejects a move whose declared content is not what landed", () => {
    const message = failureOf(() =>
      assertEffects(BEFORE, AFTER, {
        ...CLEAN_EFFECTS,
        moved: { "src/utils.ts": { to: "lib/utils.ts", content: "not what landed\n" } },
      }),
    );

    expect(message).toContain("lib/utils.ts content after the move");
  });

  it("rejects a file listed as `changed` that was left alone", () => {
    const message = failureOf(() =>
      assertEffects(BEFORE, AFTER, {
        ...CLEAN_EFFECTS,
        changed: { ...CLEAN_EFFECTS.changed, "tsconfig.json": BEFORE["tsconfig.json"] },
      }),
    );

    expect(message).toContain("tsconfig.json was listed as changed but is identical");
  });

  it("rejects a move whose declared destination is not where the file landed", () => {
    const message = failureOf(() =>
      assertEffects(
        BEFORE,
        AFTER,
        effectsOf({ moved: { "src/utils.ts": { to: "lib/elsewhere.ts" } } }),
      ),
    );

    expect(message).toContain("lib/elsewhere.ts should exist, with content intact");
  });

  it("rejects a declared move whose source is still sitting there", () => {
    // A copy that leaves the original behind passes the totality check — the source is
    // byte-identical, so nothing reads as changed. Only this assertion catches it.
    const message = failureOf(() =>
      assertEffects(
        BEFORE,
        { ...BEFORE, "lib/tsconfig.json": BEFORE["tsconfig.json"] },
        effectsOf({ moved: { "tsconfig.json": { to: "lib/tsconfig.json" } } }),
      ),
    );

    expect(message).toContain("tsconfig.json should have moved away");
  });

  it("rejects a file declared `unchanged` that was rewritten", () => {
    const message = failureOf(() =>
      assertEffects(BEFORE, AFTER, {
        ...CLEAN_EFFECTS,
        changed: {},
        unchanged: ["src/main.ts"],
      }),
    );

    expect(message).toContain("src/main.ts should have been left alone");
  });

  it("rejects `unchanged` naming a file that never existed", () => {
    const message = failureOf(() =>
      assertEffects(BEFORE, BEFORE, effectsOf({ unchanged: ["src/never-existed.ts"] })),
    );

    expect(message).toContain("src/never-existed.ts should have existed beforehand");
  });

  it("rejects a `moved` entry whose source was never in the workspace", () => {
    // Both halves of the move assertion read as satisfied when the source is absent: nothing
    // is there afterwards, and the destination matches the source's equally absent content.
    const message = failureOf(() =>
      assertEffects(BEFORE, AFTER, {
        ...CLEAN_EFFECTS,
        moved: { ...CLEAN_EFFECTS.moved, "src/ghost.ts": { to: "lib/ghost.ts" } },
      }),
    );

    expect(message).toContain("src/ghost.ts");
  });
});

describe("response contract", () => {
  it("passes when the written block, sugar expanded, is exactly what was returned", () => {
    assertResponseMatches(WRITTEN_RESPONSE, SCRUBBED_RESPONSE);
  });

  it("rejects a written response whose field value is wrong", () => {
    const message = failureOf(() =>
      assertResponseMatches({ ...WRITTEN_RESPONSE, status: "warn" }, SCRUBBED_RESPONSE),
    );

    expect(message).toContain("response:");
    expect(message).toContain("warn");
  });

  it("rejects a written response that omits a field the dispatcher returns", () => {
    const { typeErrors: _sugar, ...omitted } = WRITTEN_RESPONSE;

    const message = failureOf(() => assertResponseMatches(omitted, SCRUBBED_RESPONSE));

    // Exact equality is what stops a consumer-visible field being dropped unnoticed.
    expect(message).toContain("response:");
    expect(message).toContain("to deeply equal");
  });

  it("rejects a written response carrying a field the dispatcher never returns", () => {
    const message = failureOf(() =>
      assertResponseMatches({ ...WRITTEN_RESPONSE, invented: true }, SCRUBBED_RESPONSE),
    );

    expect(message).toContain("response:");
  });
});

describe("step status", () => {
  it("rejects an `error` status, naming the step and its message", () => {
    const message = failureOf(() =>
      assertStepSucceeded("moveFile", {
        status: "error",
        error: "FILE_NOT_FOUND",
        message: "File not found: src/missing.ts",
      }),
    );

    expect(message).toContain("step `moveFile` status");
    expect(message).toContain("File not found: src/missing.ts");
  });

  it("passes `success`", () => {
    assertStepSucceeded("moveFile", { status: "success" });
  });

  it("passes `warn`, a success that also reported a type error", () => {
    assertStepSucceeded("moveFile", { status: "warn", typeErrorCount: 1 });
  });
});

describe("failure description", () => {
  it("puts the description in front of the failure, so a deliberate expectation reads as one", () => {
    const error = new Error("files changed without being named in `then.files`");

    const described = describeFailure(error, "the stale path is expected");

    expect(described).toBe(error);
    expect(error.message).toBe(
      "the stale path is expected\n\nfiles changed without being named in `then.files`",
    );
  });

  it("leaves the failure alone when there is no description", () => {
    const error = new Error("files changed without being named in `then.files`");

    const returned = describeFailure(error, undefined);

    expect(returned).toBe(error);
    expect(error.message).toBe("files changed without being named in `then.files`");
  });

  it("returns a non-Error failure unchanged", () => {
    expect(describeFailure("something threw", "a description")).toBe("something threw");
  });
});

/**
 * A scenario over the shared workspace, with the step list and outcome block per case.
 *
 * Call sites say `outcome` so the format's `then` key appears once, here. A scenario is
 * never awaited, so being thenable is inert, and one suppression beats one per case.
 */
function scenarioOf(parts: {
  name: string;
  description?: string;
  when: Scenario["when"];
  outcome: Scenario["then"];
}): Scenario {
  return {
    name: parts.name,
    description: parts.description,
    given: { files: BEFORE },
    when: parts.when,
    // biome-ignore lint/suspicious/noThenProperty: the Given/When/Then vocabulary of the format under test.
    then: parts.outcome,
  };
}

function scenarioFileOf(scenario: Scenario): ScenarioFile {
  return { fixtures: {}, scenarios: [scenario] };
}

describe("executor wiring", () => {
  test("scrubs the temp root so a passing response reads as workspace-relative", async ({
    dir,
  }) => {
    const file = scenarioFileOf(
      scenarioOf({
        name: "a single move with its response stated",
        when: [{ moveFile: { oldPath: "src/utils.ts", newPath: "lib/utils.ts" } }],
        outcome: { response: WRITTEN_RESPONSE, files: CLEAN_EFFECTS },
      }),
    );

    await expect(executeScenario(file.scenarios[0], file, dir)).resolves.toBeUndefined();
  });

  test("puts the description in front of the failure, so a deliberate expectation reads as one", async ({
    dir,
  }) => {
    const file = scenarioFileOf(
      scenarioOf({
        name: "a deliberately wrong expectation",
        description: "the scan never considers this specifier, so the stale path is expected",
        when: [{ moveFile: { oldPath: "src/utils.ts", newPath: "lib/utils.ts" } }],
        outcome: {
          response: WRITTEN_RESPONSE,
          files: effectsOf({ moved: { "src/utils.ts": { to: "lib/utils.ts" } } }),
        },
      }),
    );

    // Two pattern assertions against the one stored rejection both run.
    const execution = executeScenario(file.scenarios[0], file, dir);

    await expect(execution).rejects.toThrow(/^the scan never considers this specifier/);
    await expect(execution).rejects.toThrow("files changed without being named in `then.files`");
  });

  test("runs every step of a sequence and judges the net effects, since no step states a response", async ({
    dir,
  }) => {
    const file = scenarioFileOf(
      scenarioOf({
        name: "two moves in turn",
        when: [
          { moveFile: { oldPath: "src/utils.ts", newPath: "lib/utils.ts" } },
          { moveFile: { oldPath: "lib/utils.ts", newPath: "dist/utils.ts" } },
        ],
        outcome: {
          files: {
            moved: { "src/utils.ts": { to: "dist/utils.ts" } },
            changed: {
              "src/main.ts": `import { greetUser } from "../dist/utils";

console.log(greetUser("World"));
`,
            },
            unchanged: ["tsconfig.json"],
          },
        },
      }),
    );

    await expect(executeScenario(file.scenarios[0], file, dir)).resolves.toBeUndefined();
  });

  test("stops a sequence at the first step that fails, naming it", async ({ dir }) => {
    const file = scenarioFileOf(
      scenarioOf({
        name: "a second move that finds no file",
        when: [
          { moveFile: { oldPath: "src/utils.ts", newPath: "lib/utils.ts" } },
          { moveFile: { oldPath: "src/missing.ts", newPath: "lib/missing.ts" } },
        ],
        outcome: { files: effectsOf() },
      }),
    );

    const execution = executeScenario(file.scenarios[0], file, dir);

    // The dispatcher's message carries the absolute path; the tail names the file.
    await expect(execution).rejects.toThrow("step `moveFile` status");
    await expect(execution).rejects.toThrow("src/missing.ts");
  });

  test("rejects a stated response that is not what the dispatcher returned", async ({ dir }) => {
    const file = scenarioFileOf(
      scenarioOf({
        name: "a move whose stated response gets the status wrong",
        when: [{ moveFile: { oldPath: "src/utils.ts", newPath: "lib/utils.ts" } }],
        outcome: {
          response: { ...WRITTEN_RESPONSE, status: "warn" },
          files: CLEAN_EFFECTS,
        },
      }),
    );

    const execution = executeScenario(file.scenarios[0], file, dir);

    // The file effects all hold, so only the response assertion can catch the wrong status.
    await expect(execution).rejects.toThrow("response:");
    await expect(execution).rejects.toThrow("warn");
  });
});

