import * as fs from "node:fs";
import * as path from "node:path";
import { describe, expect } from "vitest";
import { FIXTURES, fileExists, readFile, fixtureTest as test } from "../__testHelpers__/helpers.js";
import { WorkspaceScope } from "../domain/workspace-scope.js";
import { NodeFileSystem } from "../ports/node-filesystem.js";
import { tsDeleteFile } from "./delete-file.js";
import { TsMorphEngine } from "./engine.js";

function makeScope(workspace: string): WorkspaceScope {
  return new WorkspaceScope(workspace, new NodeFileSystem());
}

describe("tsDeleteFile", () => {
  describe("in-project TS/JS importer removal", () => {
    test("removes named import declarations that reference the deleted file", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
      const scope = makeScope(dir);
      await tsDeleteFile(new TsMorphEngine(), `${dir}/src/target.ts`, scope);

      expect(scope.modified).toContain(`${dir}/src/importer.ts`);
      expect(readFile(dir, "src/importer.ts")).not.toMatch(/from ['"]\.\/target['"]/);
    });

    test("removes type-only import declarations that reference the deleted file", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
      const scope = makeScope(dir);
      await tsDeleteFile(new TsMorphEngine(), `${dir}/src/target.ts`, scope);

      const content = readFile(dir, "src/importer.ts");
      expect(content).not.toMatch(/import type.*from ['"]\.\/target['"]/);
    });

    test("removes export * and named re-export declarations from barrel files", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
      const scope = makeScope(dir);
      await tsDeleteFile(new TsMorphEngine(), `${dir}/src/target.ts`, scope);

      expect(scope.modified).toContain(`${dir}/src/barrel.ts`);
      const content = readFile(dir, "src/barrel.ts");
      expect(content).not.toMatch(/from ['"]\.\/target['"]/);
    });

    test("returns importRefsRemoved = 0 when nothing imports the file", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
      const isolated = path.join(dir, "src", "isolated.ts");
      fs.writeFileSync(isolated, "export const x = 1;\n", "utf8");

      const scope = makeScope(dir);
      const result = await tsDeleteFile(new TsMorphEngine(), isolated, scope);

      expect(result.importRefsRemoved).toBe(0);
      expect(scope.modified).toHaveLength(0);
    });
  });

  describe("workspace-wide importer removal", () => {
    test("removes imports from files not included in tsconfig.include", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
      // TsMorphEngine(dir) expands the project graph to include all workspace files,
      // so tests/out-of-project.ts is handled by the in-project phase.
      const scope = makeScope(dir);
      await tsDeleteFile(new TsMorphEngine(dir), `${dir}/src/target.ts`, scope);

      expect(scope.modified).toContain(`${dir}/tests/out-of-project.ts`);
      expect(readFile(dir, "tests/out-of-project.ts")).not.toMatch(/from ['"][^'"]*target['"]/);
    });

    test("handles imports that use an explicit file extension", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
      const extra = path.join(dir, "tests", "explicit-ext.ts");
      fs.writeFileSync(
        extra,
        'import { targetFn } from "../src/target.ts";\nconst _ = targetFn();\n',
        "utf8",
      );

      const scope = makeScope(dir);
      await tsDeleteFile(new TsMorphEngine(dir), `${dir}/src/target.ts`, scope);

      expect(scope.modified).toContain(extra);
      expect(fs.readFileSync(extra, "utf8")).not.toMatch(/from ['"][^'"]*target/);
    });
  });

  describe("physical file deletion", () => {
    test("removes the target file from disk after cleaning importers", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
      expect(fileExists(dir, "src/target.ts")).toBe(true);
      const scope = makeScope(dir);
      await tsDeleteFile(new TsMorphEngine(), `${dir}/src/target.ts`, scope);

      expect(fileExists(dir, "src/target.ts")).toBe(false);
    });

    test("deletes the file even when it has no importers", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
      const isolated = path.join(dir, "src", "isolated.ts");
      fs.writeFileSync(isolated, "export const x = 1;\n", "utf8");

      const scope = makeScope(dir);
      await tsDeleteFile(new TsMorphEngine(), isolated, scope);

      expect(fs.existsSync(isolated)).toBe(false);
    });
  });

  describe("import ref counts", () => {
    test("counts every removed TS declaration in importRefsRemoved", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
      // importer.ts: 2 decls (named import + type import)
      // barrel.ts:   2 decls (export * + named re-export)
      // tests/out-of-project.ts: 1 decl (included via expanded project graph)
      const scope = makeScope(dir);
      const result = await tsDeleteFile(new TsMorphEngine(dir), `${dir}/src/target.ts`, scope);

      expect(result.importRefsRemoved).toBe(5);
    });
  });

  describe("workspace boundary", () => {
    test("skips out-of-workspace importers without writing them", async ({ seedNamedFixture }) => {
      const root = await seedNamedFixture(FIXTURES.crossBoundary.name);
      const workspace = path.join(root, "workspace");
      const targetFile = path.join(workspace, "src", "utils.ts");
      const consumerFile = path.join(root, "consumer", "main.ts");
      const consumerBefore = fs.readFileSync(consumerFile, "utf8");

      const scope = makeScope(workspace);
      await tsDeleteFile(new TsMorphEngine(), targetFile, scope);

      expect(fs.readFileSync(consumerFile, "utf8")).toBe(consumerBefore);
      expect(scope.skipped).toContain(consumerFile);
      expect(fs.existsSync(targetFile)).toBe(false);
    });
    test("only records files within the workspace in scope.modified", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
      const scope = makeScope(dir);
      await tsDeleteFile(new TsMorphEngine(), `${dir}/src/target.ts`, scope);

      for (const f of scope.modified) {
        expect(f.startsWith(dir)).toBe(true);
      }
    });
  });
});

src/daemon/dispatcher-vue-routing.test.t.source:
import * as path from "node:path";
import { describe, expect } from "vitest";
import { FIXTURES, readFile, fixtureTest as test } from "../__testHelpers__/helpers.js";
import { dispatchRequest } from "./dispatcher.js";

describe("dispatchRequest getTypeErrors engine routing in a Vue project", () => {
  test("single-file call on a .vue file returns that file's diagnostics instead of throwing", async ({
    seedNamedFixture,
  }) => {
    const dir = await seedNamedFixture(FIXTURES.vueErrors.name);
    const file = path.join(dir, "src/Broken.vue");

    const result = (await dispatchRequest(
      { method: "getTypeErrors", params: { file } },
      dir,
    )) as Record<string, unknown>;

    expect(result.status).toBe("success");
    const diagnostics = result.diagnostics as Array<{ file: string; code: number }>;
    expect(diagnostics.length).toBeGreaterThan(0);
    expect(diagnostics.every((d) => d.file === file)).toBe(true);
    expect(result.errorCount).toBe(diagnostics.length);
  }, 15_000);

  test("single-file call on a .ts file in the same Vue project also routes through VolarEngine without throwing", async ({
    seedNamedFixture,
  }) => {
    const dir = await seedNamedFixture(FIXTURES.vueErrors.name);
    const file = path.join(dir, "src/utils.ts");

    const result = (await dispatchRequest(
      { method: "getTypeErrors", params: { file } },
      dir,
    )) as Record<string, unknown>;

    expect(result.status).toBe("success");
    const diagnostics = result.diagnostics as Array<{ file: string; code: number }>;
    expect(diagnostics.length).toBeGreaterThan(0);
    expect(diagnostics.every((d) => d.file === file)).toBe(true);
  }, 15_000);

  test("project-wide call (no file param) includes diagnostics from both .ts and .vue files", async ({
    seedNamedFixture,
  }) => {
    const dir = await seedNamedFixture(FIXTURES.vueErrors.name);

    const result = (await dispatchRequest({ method: "getTypeErrors", params: {} }, dir)) as Record<
      string,
      unknown
    >;

    expect(result.status).toBe("success");
    const diagnostics = result.diagnostics as Array<{ file: string }>;
    expect(diagnostics.some((d) => d.file.endsWith(".ts"))).toBe(true);
    expect(diagnostics.some((d) => d.file.endsWith(".vue"))).toBe(true);
    expect(result.errorCount).toBe(diagnostics.length);
  }, 15_000);

  test("project-wide call on a non-Vue project is unaffected — same diagnostics as before the fix", async ({
    seedNamedFixture,
  }) => {
    const dir = await seedNamedFixture(FIXTURES.tsErrors.name);

    const result = (await dispatchRequest({ method: "getTypeErrors", params: {} }, dir)) as Record<
      string,
      unknown
    >;

    expect(result.status).toBe("success");
    const diagnostics = result.diagnostics as Array<{ file: string }>;
    expect(diagnostics.length).toBeGreaterThan(0);
    expect(diagnostics.every((d) => d.file.endsWith(".ts"))).toBe(true);
    expect(diagnostics.every((d) => !d.file.endsWith(".vue"))).toBe(true);
  }, 15_000);

  test("single-file call resolves the tsconfig nearest the given file, not the workspace root's", async ({
    seedInlineFixture,
  }) => {
    // Workspace root has a plain TS-only tsconfig with no .vue awareness; the requested
    // file lives in a nested project with its own tsconfig that does include .vue files.
    // Routing off the file (not the workspace root) is what selects VolarEngine here.
    const dir = await seedInlineFixture({
      "tsconfig.json": JSON.stringify({
        compilerOptions: { strict: true },
        include: ["outer.ts"],
      }),
      "outer.ts": "export const outer: string = 'hello';\n",
      "sub/tsconfig.json": JSON.stringify({
        compilerOptions: {
          strict: true,
          target: "ESNext",
          module: "ESNext",
          moduleResolution: "bundler",
          jsx: "preserve",
        },
        include: ["**/*.ts", "**/*.vue"],
      }),
      "sub/Broken.vue":
        '<script setup lang="ts">\nconst x: number = "hello";\n</script>\n<template><div>{{ x }}</div></template>\n',
    });
    const file = path.join(dir, "sub/Broken.vue");

    const result = (await dispatchRequest(
      { method: "getTypeErrors", params: { file } },
      dir,
    )) as Record<string, unknown>;

    expect(result.status).toBe("success");
    const diagnostics = result.diagnostics as Array<{ file: string; code: number }>;
    expect(diagnostics.length).toBeGreaterThan(0);
    expect(diagnostics.every((d) => d.file === file)).toBe(true);
  }, 15_000);
});

describe("dispatchRequest engine routing for path-param operations", () => {
  test("routes off the path param, not the workspace root, so a nested project's .vue references are rewritten", async ({
    seedInlineFixture,
  }) => {
    // The workspace root's tsconfig is TS-only and does not include sub/ at all.
    // Only the nested tsconfig knows about .vue, so the .vue reference is rewritten
    // exclusively when the engine is resolved from the renamed file's own path.
    const dir = await seedInlineFixture({
      "tsconfig.json": JSON.stringify({
        compilerOptions: { strict: true },
        include: ["outer.ts"],
      }),
      "outer.ts": "export const outer: string = 'hello';\n",
      "sub/tsconfig.json": JSON.stringify({
        compilerOptions: {
          strict: true,
          target: "ESNext",
          module: "ESNext",
          moduleResolution: "bundler",
          jsx: "preserve",
        },
        include: ["**/*.ts", "**/*.vue"],
      }),
      "sub/helpers.ts": "export function greet(): string {\n  return 'hi';\n}\n",
      "sub/App.vue":
        '<script setup lang="ts">\nimport { greet } from "./helpers";\nconst msg = greet();\n</script>\n<template><div>{{ msg }}</div></template>\n',
    });

    const result = (await dispatchRequest(
      {
        method: "rename",
        params: { file: path.join(dir, "sub/helpers.ts"), line: 1, col: 17, newName: "salute" },
      },
      dir,
    )) as Record<string, unknown>;

    expect(result.status).toBe("success");

    const vue = readFile(dir, "sub/App.vue");
    expect(vue).toContain("salute");
    expect(vue).not.toContain("greet");
  }, 15_000);
});

