import { describe, expect, it } from "vitest";
import { FIXTURES, fixtureTest as test } from "../__testHelpers__/helpers.js";
import { VolarEngine } from "../plugins/vue/engine.js";
import { InMemoryFileSystem } from "../ports/in-memory-filesystem.js";
import { NodeFileSystem } from "../ports/node-filesystem.js";
import { makeMockCompiler } from "../ts-engine/__testHelpers__/mock-compiler.js";
import { TsMorphEngine } from "../ts-engine/engine.js";
import { findImporters } from "./findImporters.js";

const nodeFs = new NodeFileSystem();

describe("findImporters", () => {
  test("returns all files that import the given file", async ({ seedNamedFixture }) => {
    const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
    const compiler = new TsMorphEngine();

    const result = await findImporters(compiler, `${dir}/src/utils.ts`, nodeFs);

    expect(result.fileName).toBe("utils.ts");
    expect(result.references.length).toBeGreaterThanOrEqual(1);
    expect(result.references.some((r) => r.file.endsWith("main.ts"))).toBe(true);
    for (const ref of result.references) {
      expect(ref.line).toBeGreaterThan(0);
      expect(ref.col).toBeGreaterThan(0);
      expect(ref.length).toBeGreaterThan(0);
    }
  });

  test("returns empty references for a file with no importers", async ({ seedNamedFixture }) => {
    const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
    const compiler = new TsMorphEngine();

    const result = await findImporters(compiler, `${dir}/src/main.ts`, nodeFs);

    expect(result.fileName).toBe("main.ts");
    expect(result.references).toEqual([]);
  });

  test("throws FILE_NOT_FOUND for a non-existent file", async ({ seedNamedFixture }) => {
    const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
    const compiler = new TsMorphEngine();

    await expect(
      findImporters(compiler, `${dir}/src/doesNotExist.ts`, nodeFs),
    ).rejects.toMatchObject({
      code: "FILE_NOT_FOUND",
    });
  });

  it("resolves existence from the injected fs, not real disk", async () => {
    // File seeded only in memory — the inline node:fs.existsSync it replaced
    // would throw FILE_NOT_FOUND here.
    const memFs = new InMemoryFileSystem();
    memFs.writeFile("/ws/src/a.ts", "");
    const compiler = makeMockCompiler({
      getFileReferences: async () => [
        { fileName: "/ws/src/b.ts", textSpan: { start: 0, length: 3 } },
      ],
      readFile: () => "import './a'",
    });

    const result = await findImporters(compiler, "/ws/src/a.ts", memFs);

    expect(result.fileName).toBe("a.ts");
    expect(result.references).toHaveLength(1);
  });

  describe("with VolarEngine", () => {
    test(".ts target imported by both .ts and .vue files returns references from both", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.vueTsBoundary.name);
      const compiler = new VolarEngine(new TsMorphEngine(), dir);

      const result = await findImporters(compiler, `${dir}/src/utils.ts`, nodeFs);

      expect(result.fileName).toBe("utils.ts");
      expect(result.references.length).toBeGreaterThanOrEqual(1);
      expect(result.references.some((r) => r.file.endsWith("App.vue"))).toBe(true);
      for (const ref of result.references) {
        expect(ref.line).toBeGreaterThan(0);
        expect(ref.col).toBeGreaterThan(0);
        expect(ref.length).toBeGreaterThan(0);
      }
    });
  });

  describe("with VolarEngine — .vue target", () => {
    test(".vue target imported by another file returns references with correct positions", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.moveDirVue.name);
      const compiler = new VolarEngine(new TsMorphEngine(), dir);

      const result = await findImporters(compiler, `${dir}/src/components/Button.vue`, nodeFs);

      expect(result.fileName).toBe("Button.vue");
      expect(result.references.length).toBeGreaterThanOrEqual(1);
      expect(result.references.some((r) => r.file.endsWith("App.vue"))).toBe(true);
      for (const ref of result.references) {
        expect(ref.line).toBeGreaterThan(0);
        expect(ref.col).toBeGreaterThan(0);
        expect(ref.length).toBeGreaterThan(0);
      }
    });
  });
});

src/daemon/dispatcher-self-write.test.ts.source:
import * as path from "node:path";
import { describe, expect } from "vitest";
import { fixtureTest as test } from "../__testHelpers__/helpers.js";
import { dispatchRequest } from "./dispatcher.js";
import { shouldSuppressSelfWrite } from "./self-write-state.js";

/**
 * The ledger only sees a write that went through the shared filesystem, so
 * these drive a real operation through `dispatchRequest` rather than writing
 * through the shared instance directly. An operation that built its own
 * `FileSystem` would still pass every test that does the latter.
 */
describe("a write dispatched through the daemon", () => {
  test("is recorded, so its own watcher event is suppressed", async ({ seedInlineFixture }) => {
    const dir = await seedInlineFixture({
      "tsconfig.json": JSON.stringify({ include: ["src"] }),
      "src/greet.ts": "export const greeting = 'hello';\n",
    });
    const file = path.join(dir, "src/greet.ts");

    const result = await dispatchRequest(
      {
        method: "replaceText",
        params: { pattern: "hello", replacement: "goodbye", workspace: dir },
      },
      dir,
    );
    expect(result.status).not.toBe("error");

    expect(shouldSuppressSelfWrite(file)).toBe(true);
  });

  test("leaves a file it did not touch unsuppressed", async ({ seedInlineFixture }) => {
    const dir = await seedInlineFixture({
      "tsconfig.json": JSON.stringify({ include: ["src"] }),
      "src/greet.ts": "export const greeting = 'hello';\n",
      "src/untouched.ts": "export const other = 'hello';\n",
    });

    await dispatchRequest(
      {
        method: "replaceText",
        params: {
          pattern: "hello",
          replacement: "goodbye",
          glob: "src/greet.ts",
          workspace: dir,
        },
      },
      dir,
    );

    expect(shouldSuppressSelfWrite(path.join(dir, "src/untouched.ts"))).toBe(false);
  });
});

src/utils/file-walk.test.ts.source:
import { execSync } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { InMemoryFileSystem } from "../ports/in-memory-filesystem.js";
import { walkFiles, walkWorkspaceFiles } from "./file-walk.js";

describe("walkFiles", () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "file-walk-test-"));
  });

  afterEach(() => {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  function write(relPath: string, content = ""): string {
    const full = path.join(tmpDir, relPath);
    fs.mkdirSync(path.dirname(full), { recursive: true });
    fs.writeFileSync(full, content, "utf8");
    return full;
  }

  // ── non-git fallback ──────────────────────────────────────────────────────

  describe("non-git fallback (no .git dir)", () => {
    it("returns empty array when the directory does not exist", () => {
      // Exercises the walkRecursive try/catch path: readdirSync fails → []
      const nonExistent = path.join(tmpDir, "does-not-exist");
      const result = walkFiles(nonExistent, [".ts"]);
      expect(result).toEqual([]);
    });

    it("returns files matching extensions", () => {
      write("a.ts");
      write("b.tsx");
      write("c.vue");
      write("d.js"); // not requested

      const result = walkFiles(tmpDir, [".ts", ".tsx"]);
      const names = result.map((f) => path.basename(f)).sort();
      expect(names).toEqual(["a.ts", "b.tsx"]);
    });

    it("recurses into subdirectories", () => {
      write("src/a.ts");
      write("lib/b.ts");

      const result = walkFiles(tmpDir, [".ts"]);
      expect(result).toHaveLength(2);
    });

    it.each([
      ["node_modules", "node_modules/dep/index.ts"],
      ["dist", "dist/bundle.ts"],
      [".git", ".git/objects/a.ts"],
      [".nuxt", ".nuxt/a.ts"],
      [".output", ".output/a.ts"],
      [".vite", ".vite/a.ts"],
    ])("skips %s", (_dir, skippedFile) => {
      write("src/a.ts");
      write(skippedFile);
      expect(walkFiles(tmpDir, [".ts"])).toHaveLength(1);
    });

    it("returns .vue files when requested", () => {
      write("src/Comp.vue");
      write("src/utils.ts");

      const result = walkFiles(tmpDir, [".vue"]);
      expect(result).toHaveLength(1);
      expect(path.basename(result[0])).toBe("Comp.vue");
    });

    it("returns empty array when no matching files", () => {
      write("a.js");
      expect(walkFiles(tmpDir, [".ts"])).toEqual([]);
    });

    it("returns absolute paths", () => {
      write("src/a.ts");
      const result = walkFiles(tmpDir, [".ts"]);
      expect(path.isAbsolute(result[0])).toBe(true);
    });

    it("does not follow symlinks, so a symlink cycle cannot hang the walk", () => {
      // src/loop → tmpDir is a real cycle: tmpDir contains src, which contains
      // loop. A walk that stat-followed the link would recurse src/loop/src/loop…
      // forever. Because a symlink is neither isFile() nor isDirectory() it is
      // skipped outright — the cycle never begins and only the real file returns.
      write("src/a.ts");
      fs.symlinkSync(tmpDir, path.join(tmpDir, "src", "loop"));

      const result = walkFiles(tmpDir, [".ts"]);
      expect(result.map((f) => path.basename(f))).toEqual(["a.ts"]);
    });
  });

  // ── git repo ──────────────────────────────────────────────────────────────

  describe("git repo", () => {
    const gitEnv = { ...process.env, GIT_CONFIG_NOSYSTEM: "1", GIT_CONFIG_GLOBAL: "/dev/null" };

    function initGit() {
      execSync("git init", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });
      execSync("git config user.email test@test.com", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });
      execSync("git config user.name Test", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });
    }

    it("returns staged .ts files", () => {
      initGit();
      write("src/a.ts");
      execSync("git add .", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });

      const result = walkFiles(tmpDir, [".ts"]);
      expect(result.map((f) => path.basename(f))).toContain("a.ts");
    });

    it("includes untracked files that are not gitignored", () => {
      initGit();
      write("src/a.ts");
      write("src/b.ts");
      execSync("git add src/a.ts", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });
      // b.ts is untracked but not ignored — should still appear

      const result = walkFiles(tmpDir, [".ts"]);
      const names = result.map((f) => path.basename(f)).sort();
      expect(names).toContain("a.ts");
      expect(names).toContain("b.ts");
    });

    it("excludes gitignored files", () => {
      initGit();
      write(".gitignore", "dist/\n");
      write("src/a.ts");
      write("dist/b.ts"); // gitignored
      execSync("git add .", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });

      const result = walkFiles(tmpDir, [".ts"]);
      const names = result.map((f) => path.basename(f));
      expect(names).toContain("a.ts");
      expect(names).not.toContain("b.ts");
    });

    it("returns absolute paths", () => {
      initGit();
      write("src/a.ts");
      execSync("git add .", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });

      const result = walkFiles(tmpDir, [".ts"]);
      expect(result.length).toBeGreaterThan(0);
      expect(path.isAbsolute(result[0])).toBe(true);
    });

    it("excludes gitignored files in directories not in SKIP_DIRS", () => {
      // "private/" is not in SKIP_DIRS, so the recursive fallback would include it.
      // This test ensures git mode (not the fallback) runs and respects .gitignore.
      initGit();
      write(".gitignore", "private/\n");
      write("src/a.ts");
      write("private/secret.ts");
      execSync("git add .", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });

      const result = walkFiles(tmpDir, [".ts"]);
      const names = result.map((f) => path.basename(f));
      expect(names).toContain("a.ts");
      expect(names).not.toContain("secret.ts");
    });

    it("excludes files with non-matching extensions in git mode", () => {
      // Exercises the extension filter in the git path:
      // extSet.has(path.extname(line)) must exclude non-requested extensions.
      initGit();
      write("src/a.ts");
      write("src/b.vue"); // added to git but not requested
      execSync("git add .", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });

      const result = walkFiles(tmpDir, [".ts"]);
      const names = result.map((f) => path.basename(f));
      expect(names).toContain("a.ts");
      expect(names).not.toContain("b.vue");
      expect(result).toHaveLength(1);
    });

    it("excludes git-tracked files deleted from disk", () => {
      // git ls-files --cached returns files that are tracked even if deleted.
      // walkFiles must filter these out to avoid ENOENT when callers read them.
      initGit();
      write("src/a.ts");
      write("src/b.ts");
      execSync("git add .", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });
      execSync('git commit -m "init"', { cwd: tmpDir, env: gitEnv, stdio: "pipe" });

      // Delete b.ts from disk but don't stage the deletion
      fs.unlinkSync(path.join(tmpDir, "src/b.ts"));

      const result = walkFiles(tmpDir, [".ts"]);
      const names = result.map((f) => path.basename(f));
      expect(names).toContain("a.ts");
      expect(names).not.toContain("b.ts");
    });
  });
});

describe("walkWorkspaceFiles", () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "walk-workspace-test-"));
  });

  afterEach(() => {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  function write(relPath: string, content = ""): string {
    const full = path.join(tmpDir, relPath);
    fs.mkdirSync(path.dirname(full), { recursive: true });
    fs.writeFileSync(full, content, "utf8");
    return full;
  }

  // ── non-git fallback ──────────────────────────────────────────────────────

  describe("non-git fallback (no .git dir)", () => {
    it("returns all files when no glob is given", () => {
      write("src/a.ts");
      write("src/b.js");
      write("README.md");

      const result = walkWorkspaceFiles(tmpDir);
      const names = result.map((f) => path.basename(f)).sort();
      expect(names).toEqual(["README.md", "a.ts", "b.js"]);
    });

    it("returns empty array when directory does not exist", () => {
      const nonExistent = path.join(tmpDir, "does-not-exist");
      expect(walkWorkspaceFiles(nonExistent)).toEqual([]);
    });

    it("excludes symlinks — only real files are returned", () => {
      // No extension filter here, so a symlink erroneously treated as a file
      // would surface. It must not: a symlink is neither isFile nor isDirectory.
      write("src/a.ts");
      fs.symlinkSync(path.join(tmpDir, "src", "a.ts"), path.join(tmpDir, "src", "link.ts"));

      const result = walkWorkspaceFiles(tmpDir);
      expect(result.map((f) => path.basename(f))).toEqual(["a.ts"]);
    });

    it("filters by glob pattern", () => {
      write("src/a.ts");
      write("src/b.js");
      write("src/c.vue");

      const result = walkWorkspaceFiles(tmpDir, { glob: "**/*.ts" });
      const names = result.map((f) => path.basename(f));
      expect(names).toContain("a.ts");
      expect(names).not.toContain("b.js");
      expect(names).not.toContain("c.vue");
    });

    it("skips SKIP_DIRS", () => {
      write("src/a.ts");
      write("node_modules/dep/index.ts");
      write("dist/bundle.ts");

      const result = walkWorkspaceFiles(tmpDir);
      const names = result.map((f) => path.basename(f));
      expect(names).toContain("a.ts");
      expect(names).not.toContain("index.ts");
      expect(names).not.toContain("bundle.ts");
    });

    it("returns absolute paths", () => {
      write("src/a.ts");
      const result = walkWorkspaceFiles(tmpDir);
      expect(result.length).toBeGreaterThan(0);
      expect(path.isAbsolute(result[0])).toBe(true);
    });

    it("glob matching a basename pattern matches across all directories", () => {
      write("src/main.ts");
      write("lib/main.ts");
      write("src/utils.ts");

      const result = walkWorkspaceFiles(tmpDir, { glob: "main.ts" });
      const names = result.map((f) => path.basename(f));
      expect(names.every((n) => n === "main.ts")).toBe(true);
      expect(result).toHaveLength(2);
    });
  });

  // ── git repo ──────────────────────────────────────────────────────────────

  describe("git repo", () => {
    const gitEnv = { ...process.env, GIT_CONFIG_NOSYSTEM: "1", GIT_CONFIG_GLOBAL: "/dev/null" };

    function initGit() {
      execSync("git init", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });
      execSync("git config user.email test@test.com", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });
      execSync("git config user.name Test", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });
    }

    it("returns all tracked and untracked files without a glob", () => {
      initGit();
      write("src/a.ts");
      write("src/b.js");
      execSync("git add src/a.ts", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });
      // b.js is untracked

      const result = walkWorkspaceFiles(tmpDir);
      const names = result.map((f) => path.basename(f)).sort();
      expect(names).toContain("a.ts");
      expect(names).toContain("b.js");
    });

    it("excludes gitignored files", () => {
      initGit();
      write(".gitignore", "dist/\n");
      write("src/a.ts");
      write("dist/bundle.ts");
      execSync("git add .", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });

      const result = walkWorkspaceFiles(tmpDir);
      const names = result.map((f) => path.basename(f));
      expect(names).toContain("a.ts");
      expect(names).not.toContain("bundle.ts");
    });

    it("filters by glob in git mode", () => {
      initGit();
      write("src/a.ts");
      write("src/b.js");
      execSync("git add .", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });

      const result = walkWorkspaceFiles(tmpDir, { glob: "**/*.ts" });
      const names = result.map((f) => path.basename(f));
      expect(names).toContain("a.ts");
      expect(names).not.toContain("b.js");
    });

    it("excludes gitignored files in directories not in SKIP_DIRS", () => {
      // "private/" is not in SKIP_DIRS so the fallback would include it,
      // but git mode must honor .gitignore and exclude it.
      initGit();
      write(".gitignore", "private/\n");
      write("src/a.ts");
      write("private/secret.ts");
      execSync("git add .", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });

      const result = walkWorkspaceFiles(tmpDir);
      const names = result.map((f) => path.basename(f));
      expect(names).toContain("a.ts");
      expect(names).not.toContain("secret.ts");
    });

    it("all returned paths exist on disk (empty git output lines are filtered)", () => {
      // git ls-files output ends with a newline, producing an empty last element.
      // Removing filter(Boolean) would cause path.join(workspace, '') = workspace dir itself.
      initGit();
      write("src/a.ts");
      execSync("git add .", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });

      const result = walkWorkspaceFiles(tmpDir);
      for (const f of result) {
        expect(fs.statSync(f).isFile()).toBe(true);
      }
      // Exactly 1 file, not a spurious workspace-root entry
      expect(result).toHaveLength(1);
    });

    it("does not include directories in the file list", () => {
      // Verifies walkRecursive only pushes files, not directories.
      initGit();
      write("src/a.ts");
      execSync("git add .", { cwd: tmpDir, env: gitEnv, stdio: "pipe" });

      const result = walkWorkspaceFiles(tmpDir);
      for (const f of result) {
        expect(fs.statSync(f).isFile()).toBe(true);
      }
    });
  });

  describe("non-git fallback directory check", () => {
    let tmpDir2: string;

    beforeEach(() => {
      tmpDir2 = fs.mkdtempSync(path.join(os.tmpdir(), "walk-workspace-nofile-"));
    });

    afterEach(() => {
      fs.rmSync(tmpDir2, { recursive: true, force: true });
    });

    it("does not include directories in the file list from recursive walk", () => {
      // Verifies the else-if (entry.isFile()) guard: directories must not be in output.
      const srcDir = path.join(tmpDir2, "src");
      fs.mkdirSync(srcDir, { recursive: true });
      fs.writeFileSync(path.join(srcDir, "a.ts"), "");

      const result = walkWorkspaceFiles(tmpDir2);
      for (const f of result) {
        expect(fs.statSync(f).isFile()).toBe(true);
      }
      expect(result.map((f) => path.basename(f))).toContain("a.ts");
    });
  });

  describe("injected FileSystem (in-memory fallback)", () => {
    // /ws does not exist on disk, so `git ls-files` fails and the walk falls
    // back to walkRecursive over the injected in-memory port — no real disk.
    function seed(): InMemoryFileSystem {
      const vfs = new InMemoryFileSystem();
      vfs.writeFile("/ws/src/a.ts", "");
      vfs.writeFile("/ws/src/b.js", "");
      vfs.writeFile("/ws/README.md", "");
      return vfs;
    }

    it("walks the in-memory tree when no glob is given", () => {
      const result = walkWorkspaceFiles("/ws", { fs: seed() });
      expect(result.map((f) => path.basename(f)).sort()).toEqual(["README.md", "a.ts", "b.js"]);
    });

    it("applies the glob filter against the in-memory tree", () => {
      const result = walkWorkspaceFiles("/ws", { glob: "**/*.ts", fs: seed() });
      expect(result.map((f) => path.basename(f))).toEqual(["a.ts"]);
    });

    it("excludes matches from the excludeGlob after the glob filter is applied", () => {
      const vfs = new InMemoryFileSystem();
      vfs.writeFile("/ws/docs/archive/old.md", "");
      vfs.writeFile("/ws/docs/guide.md", "");
      vfs.writeFile("/ws/src/a.ts", "");

      const result = walkWorkspaceFiles("/ws", { excludeGlob: "docs/archive/**", fs: vfs });
      const names = result.map((f) => path.basename(f)).sort();
      expect(names).toEqual(["a.ts", "guide.md"]);
    });

    it("applies excludeGlob after glob, not instead of it", () => {
      const vfs = new InMemoryFileSystem();
      vfs.writeFile("/ws/docs/archive/old.md", "");
      vfs.writeFile("/ws/docs/guide.md", "");
      vfs.writeFile("/ws/src/a.ts", "");

      const result = walkWorkspaceFiles("/ws", {
        glob: "**/*.md",
        excludeGlob: "docs/archive/**",
        fs: vfs,
      });
      expect(result.map((f) => path.basename(f))).toEqual(["guide.md"]);
    });

    it("throws INVALID_GLOB for unsupported excludeGlob syntax", () => {
      expect(() => walkWorkspaceFiles("/ws", { excludeGlob: "docs/[ab]/**", fs: seed() })).toThrow(
        expect.objectContaining({ code: "INVALID_GLOB" }),
      );
    });

    it("excludeGlob brace group excludes every expanded tree", () => {
      const vfs = new InMemoryFileSystem();
      vfs.writeFile("/ws/docs/archive/old.md", "");
      vfs.writeFile("/ws/dist/bundle.js", "");
      vfs.writeFile("/ws/src/a.ts", "");

      const result = walkWorkspaceFiles("/ws", {
        excludeGlob: "{docs/archive/**,dist/**}",
        fs: vfs,
      });
      expect(result.map((f) => path.basename(f))).toEqual(["a.ts"]);
    });
  });
});

