import * as fs from "node:fs";
import { describe, expect, onTestFinished } from "vitest";
import { fileExists, readFile } from "../helpers.js";
import { FIXTURES, fixtureTest as test } from "./fixtures.js";

describe("fixtureTest fixtures", () => {
  test("dir is a fresh empty temp directory and is removed after the test", ({ dir }) => {
    expect(fs.existsSync(dir)).toBe(true);
    expect(fs.readdirSync(dir)).toHaveLength(0);
    onTestFinished(() => {
      expect(fs.existsSync(dir)).toBe(false);
    });
  });

  describe("seedInlineFixture", () => {
    test("writes files with content and creates parent directories on demand", async ({
      seedInlineFixture,
    }) => {
      const dir = await seedInlineFixture({
        "tsconfig.json": "{}",
        "src/nested/a.ts": "export {}",
      });

      expect(fileExists(dir, "tsconfig.json")).toBe(true);
      expect(readFile(dir, "tsconfig.json")).toBe("{}");

      expect(fileExists(dir, "src/nested/a.ts")).toBe(true);
      expect(readFile(dir, "src/nested/a.ts")).toBe("export {}");

      expect(fileExists(dir, "src/nested")).toBe(true);
    });

    test("returns the same dir on repeated calls within a test", async ({ seedInlineFixture }) => {
      const first = await seedInlineFixture({ "a.txt": "1" });
      const second = await seedInlineFixture({ "b.txt": "2" });
      expect(second).toBe(first);
      expect(readFile(first, "a.txt")).toBe("1");
      expect(readFile(first, "b.txt")).toBe("2");
    });

    test("is a no-op when called with an empty map", async ({ seedInlineFixture }) => {
      const dir = await seedInlineFixture({});
      expect(fs.readdirSync(dir)).toHaveLength(0);
    });
  });

  describe("seedNamedFixture", () => {
    test("copies a named fixture's directory tree into dir", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);

      const utilsContent = readFile(dir, "src/utils.ts");
      expect(utilsContent).toContain("export function greetUser");
      expect(utilsContent).toContain("Hello,");
      expect(fileExists(dir, "tsconfig.json")).toBe(true);
    });
  });

  describe("composition — seedNamedFixture then seedInlineFixture", () => {
    test("both helpers write into the same dir; later seedInlineFixture writes overwrite fixture files at the same path", async ({
      seedNamedFixture,
      seedInlineFixture,
    }) => {
      const fromNamed = await seedNamedFixture(FIXTURES.simpleTs.name);
      const fromInline = await seedInlineFixture({ "src/utils.ts": "OVERRIDDEN" });

      expect(fromInline).toBe(fromNamed);
      expect(readFile(fromNamed, "src/utils.ts")).toBe("OVERRIDDEN");
      expect(readFile(fromNamed, "src/main.ts")).toContain("greetUser");
    });
  });
});

src/daemon/paths.test.ts.source:
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { InMemoryFileSystem } from "../ports/in-memory-filesystem.js";
import { isDaemonAlive, removeDaemonFiles } from "./daemon.js";
import { ensureCacheDir, lockfilePath, socketPath } from "./paths.js";

const WORKSPACE_A = "/tmp/test-workspace-alpha";
const WORKSPACE_B = "/tmp/test-workspace-beta";
const CACHE_DIR = path.join(os.homedir(), ".cache", "weaver");

describe("socketPath / lockfilePath", () => {
  it("returns a .sock path inside the cache dir", () => {
    const p = socketPath(WORKSPACE_A);
    expect(p).toMatch(/\.sock$/);
    expect(p.startsWith(CACHE_DIR)).toBe(true);
  });

  it("returns a .pid path inside the cache dir", () => {
    const p = lockfilePath(WORKSPACE_A);
    expect(p).toMatch(/\.pid$/);
    expect(p.startsWith(CACHE_DIR)).toBe(true);
  });

  it("is deterministic — same workspace → same path", () => {
    expect(socketPath(WORKSPACE_A)).toBe(socketPath(WORKSPACE_A));
    expect(lockfilePath(WORKSPACE_A)).toBe(lockfilePath(WORKSPACE_A));
  });

  it("different workspaces → different paths", () => {
    expect(socketPath(WORKSPACE_A)).not.toBe(socketPath(WORKSPACE_B));
    expect(lockfilePath(WORKSPACE_A)).not.toBe(lockfilePath(WORKSPACE_B));
  });

  it("socket and lockfile paths are different for the same workspace", () => {
    expect(socketPath(WORKSPACE_A)).not.toBe(lockfilePath(WORKSPACE_A));
  });
});

describe("isDaemonAlive", () => {
  const testWorkspace = "/tmp/test-daemon-alive-workspace";

  beforeEach(() => {
    fs.mkdirSync(CACHE_DIR, { recursive: true });
    // Clean up any leftover files
    removeDaemonFiles(testWorkspace);
  });

  afterEach(() => {
    removeDaemonFiles(testWorkspace);
  });

  it("returns false when no lockfile exists", () => {
    expect(isDaemonAlive(testWorkspace)).toBe(false);
  });

  it("returns false when lockfile is malformed (not JSON)", () => {
    fs.writeFileSync(lockfilePath(testWorkspace), "not-a-pid");
    expect(isDaemonAlive(testWorkspace)).toBe(false);
  });

  it("returns false when lockfile contains a non-existent PID", () => {
    // PID 999999999 is extremely unlikely to exist
    fs.writeFileSync(
      lockfilePath(testWorkspace),
      JSON.stringify({ pid: 999999999, startedAt: Date.now() }),
    );
    expect(isDaemonAlive(testWorkspace)).toBe(false);
  });

  it("returns true when lockfile has a live PID and socket file exists", () => {
    fs.mkdirSync(path.dirname(socketPath(testWorkspace)), { recursive: true });
    fs.writeFileSync(socketPath(testWorkspace), "");
    fs.writeFileSync(
      lockfilePath(testWorkspace),
      JSON.stringify({ pid: process.pid, startedAt: Date.now() }),
    );
    expect(isDaemonAlive(testWorkspace)).toBe(true);
  });

  it("returns false when lockfile has a live PID but socket file is missing", () => {
    fs.writeFileSync(
      lockfilePath(testWorkspace),
      JSON.stringify({ pid: process.pid, startedAt: Date.now() }),
    );
    expect(isDaemonAlive(testWorkspace)).toBe(false);
  });

  it.each([
    ["a non-object JSON value", "42"],
    ["a JSON object missing pid", JSON.stringify({ startedAt: 1234 })],
    ["a JSON object missing startedAt", JSON.stringify({ pid: 123 })],
  ])("returns false when lockfile content is %s", (_label, lockfileContent) => {
    const memFs = new InMemoryFileSystem();
    memFs.writeFile(lockfilePath(testWorkspace), lockfileContent);
    expect(isDaemonAlive(testWorkspace, memFs)).toBe(false);
  });

  it("returns false when lockfile pid is a numeric string, even if it names a live PID and a socket file exists", () => {
    // process.kill() coerces a string pid to a number, so a lockfile with
    // pid as a string matching a real process would look "alive" if
    // readLockfile's typeof check were skipped — this pins that the
    // shape check itself (not process.kill) rejects it.
    const memFs = new InMemoryFileSystem();
    memFs.writeFile(socketPath(testWorkspace), "");
    memFs.writeFile(
      lockfilePath(testWorkspace),
      JSON.stringify({ pid: String(process.pid), startedAt: Date.now() }),
    );
    expect(isDaemonAlive(testWorkspace, memFs)).toBe(false);
  });

  it("returns false when lockfile has a non-existent PID even if a stale socket file exists", () => {
    const memFs = new InMemoryFileSystem();
    memFs.writeFile(socketPath(testWorkspace), "");
    memFs.writeFile(
      lockfilePath(testWorkspace),
      JSON.stringify({ pid: 999999999, startedAt: Date.now() }),
    );
    expect(isDaemonAlive(testWorkspace, memFs)).toBe(false);
  });
});

describe("ensureCacheDir", () => {
  it("creates the cache directory", () => {
    const memFs = new InMemoryFileSystem();
    ensureCacheDir(memFs);
    expect(memFs.exists(CACHE_DIR)).toBe(true);
  });
});

describe("removeDaemonFiles", () => {
  const testWorkspace = "/tmp/test-daemon-remove-workspace";

  beforeEach(() => {
    fs.mkdirSync(CACHE_DIR, { recursive: true });
  });

  afterEach(() => {
    removeDaemonFiles(testWorkspace);
  });

  it("removes socket and lockfile when they exist", () => {
    fs.writeFileSync(socketPath(testWorkspace), "");
    fs.writeFileSync(lockfilePath(testWorkspace), "");
    removeDaemonFiles(testWorkspace);
    expect(fs.existsSync(socketPath(testWorkspace))).toBe(false);
    expect(fs.existsSync(lockfilePath(testWorkspace))).toBe(false);
  });

  it("does not throw when files do not exist", () => {
    expect(() => removeDaemonFiles(testWorkspace)).not.toThrow();
  });
});

