import { describe, expect, it } from "vitest";
import { InMemoryFileSystem } from "../ports/in-memory-filesystem.js";
import { RecordingFileSystem } from "./recording-filesystem.js";
import { createSelfWriteLedger } from "./self-write-ledger.js";

function setup() {
  const innerFs = new InMemoryFileSystem();
  const ledger = createSelfWriteLedger(innerFs);
  const recordingFs = new RecordingFileSystem(innerFs, ledger);
  return { innerFs, ledger, recordingFs };
}

describe("RecordingFileSystem", () => {
  describe("forwarding reads", () => {
    it("reads file content through the wrapped filesystem", () => {
      const { innerFs, recordingFs } = setup();
      innerFs.writeFile("/workspace/read.ts", "hello");

      expect(recordingFs.readFile("/workspace/read.ts")).toBe("hello");
    });

    it("reports existence through the wrapped filesystem", () => {
      const { innerFs, recordingFs } = setup();
      innerFs.writeFile("/workspace/present.ts", "content");

      expect(recordingFs.exists("/workspace/present.ts")).toBe(true);
      expect(recordingFs.exists("/workspace/absent.ts")).toBe(false);
    });

    it("reports directory classification through the wrapped filesystem", () => {
      const { innerFs, recordingFs } = setup();
      innerFs.mkdir("/workspace/adir");
      innerFs.writeFile("/workspace/afile.ts", "content");

      expect(recordingFs.stat("/workspace/adir").isDirectory()).toBe(true);
      expect(recordingFs.stat("/workspace/afile.ts").isDirectory()).toBe(false);
    });

    it("lists directory entries through the wrapped filesystem", () => {
      const { innerFs, recordingFs } = setup();
      innerFs.writeFile("/workspace/dir/a.ts", "a");
      innerFs.writeFile("/workspace/dir/b.ts", "b");

      expect(
        recordingFs
          .readdir("/workspace/dir")
          .map((e) => e.name)
          .sort(),
      ).toEqual(["a.ts", "b.ts"]);
    });

    it("resolves and realpaths through the wrapped filesystem", () => {
      const { recordingFs } = setup();

      expect(recordingFs.resolve("/a", "b.ts")).toBe("/a/b.ts");
      expect(recordingFs.realpath("/a/b.ts")).toBe("/a/b.ts");
    });
  });

  describe("recording a write", () => {
    it("suppresses the next event for the written path only", () => {
      const { ledger, recordingFs } = setup();

      recordingFs.writeFile("/workspace/x.ts", "content");

      expect(ledger.shouldSuppress("/workspace/x.ts")).toBe(true);
      expect(ledger.shouldSuppress("/workspace/untouched.ts")).toBe(false);
    });
  });

  describe("recording a directory creation", () => {
    it("suppresses the next event for the created directory path", () => {
      const { ledger, recordingFs } = setup();

      recordingFs.mkdir("/workspace/newdir");

      expect(ledger.shouldSuppress("/workspace/newdir")).toBe(true);
    });
  });

  describe("recording a removal", () => {
    it("suppresses the next event for the removed path while it stays absent", () => {
      const { innerFs, ledger, recordingFs } = setup();
      innerFs.writeFile("/workspace/gone.ts", "content");

      recordingFs.unlink("/workspace/gone.ts");

      expect(ledger.shouldSuppress("/workspace/gone.ts")).toBe(true);
    });
  });

  describe("recording a file rename", () => {
    it("suppresses removal at the old path and a write at the new path", () => {
      const { innerFs, ledger, recordingFs } = setup();
      innerFs.writeFile("/workspace/a.ts", "content");

      recordingFs.rename("/workspace/a.ts", "/workspace/b.ts");

      expect(ledger.shouldSuppress("/workspace/a.ts")).toBe(true);
      expect(ledger.shouldSuppress("/workspace/b.ts")).toBe(true);
    });
  });

  describe("recording a directory rename", () => {
    it("suppresses removal and write for every file in the moved subtree, at every depth", () => {
      const { innerFs, ledger, recordingFs } = setup();
      innerFs.writeFile("/workspace/olddir/top.ts", "top");
      innerFs.mkdir("/workspace/olddir/nested");
      innerFs.writeFile("/workspace/olddir/nested/deep.ts", "deep");
      innerFs.writeFile("/workspace/untouched.ts", "keep");

      recordingFs.rename("/workspace/olddir", "/workspace/newdir");

      expect(ledger.shouldSuppress("/workspace/olddir/top.ts")).toBe(true);
      expect(ledger.shouldSuppress("/workspace/newdir/top.ts")).toBe(true);
      expect(ledger.shouldSuppress("/workspace/olddir/nested/deep.ts")).toBe(true);
      expect(ledger.shouldSuppress("/workspace/newdir/nested/deep.ts")).toBe(true);
    });

    it("does not record a directory rename's own two directory paths, only its files", () => {
      const { innerFs, ledger, recordingFs } = setup();
      innerFs.writeFile("/workspace/olddir/top.ts", "top");

      recordingFs.rename("/workspace/olddir", "/workspace/newdir");

      expect(ledger.shouldSuppress("/workspace/olddir")).toBe(false);
      expect(ledger.shouldSuppress("/workspace/newdir")).toBe(false);
    });

    it("does not suppress a file outside the moved subtree", () => {
      const { innerFs, ledger, recordingFs } = setup();
      innerFs.writeFile("/workspace/olddir/top.ts", "top");
      innerFs.writeFile("/workspace/untouched.ts", "keep");

      recordingFs.rename("/workspace/olddir", "/workspace/newdir");

      expect(ledger.shouldSuppress("/workspace/untouched.ts")).toBe(false);
    });
  });
});

src/operations/extractFunction.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import { WorkspaceScope } from "../domain/workspace-scope.js";
import { InMemoryFileSystem } from "../ports/in-memory-filesystem.js";
import type { Engine } from "../ts-engine/types.js";
import { extractFunction } from "./extractFunction.js";

function scopeWith(files: Record<string, string> = {}): WorkspaceScope {
  const vfs = new InMemoryFileSystem();
  for (const [path, content] of Object.entries(files)) {
    vfs.writeFile(path, content);
  }
  return new WorkspaceScope("/ws", vfs);
}

describe("extractFunction operation", () => {
  it("throws FILE_NOT_FOUND for a missing source file", async () => {
    const fakeEngine = {} as Engine;

    await expect(
      extractFunction(fakeEngine, "/ws/src/does-not-exist.ts", 1, 1, 1, 10, "myFn", scopeWith()),
    ).rejects.toMatchObject({ code: "FILE_NOT_FOUND" });
  });

  it("delegates to engine.extractFunction with correct arguments and returns its result", async () => {
    const filePath = "/ws/src/target.ts";
    const scope = scopeWith({ [filePath]: "export function foo() {}\n" });

    const expectedResult = {
      filesModified: [filePath],
      filesSkipped: [],
      functionName: "extracted",
      parameterCount: 1,
    };
    const mockEngine = {
      extractFunction: vi.fn().mockResolvedValue(expectedResult),
    } as unknown as Engine;

    const result = await extractFunction(mockEngine, filePath, 2, 3, 4, 19, "extracted", scope);

    expect(mockEngine.extractFunction).toHaveBeenCalledWith(
      filePath,
      2,
      3,
      4,
      19,
      "extracted",
      scope,
    );
    expect(result).toBe(expectedResult);
  });
});

src/adapters/cli/install-skills.test.ts.source:
import * as nodePath from "node:path";
import { describe, expect, it } from "vitest";
import { InMemoryFileSystem } from "../../ports/filesystem.js";
import { type InstallSkillsContext, runInstallSkills } from "./install-skills.js";

const PKG_ROOT = "/pkg";
const SOURCE = `${PKG_ROOT}/.claude/skills`;
const DEST = "/project/.claude/skills";
const SKILL_A = "weaver-refactor";
const SKILL_B = "weaver-code-inspection";
const CONTENT_A = "# Refactor skill";
const CONTENT_B = "# Code inspection skill";

interface Harness {
  fs: InMemoryFileSystem;
  lines: string[];
  context: InstallSkillsContext;
}

/**
 * Seed an in-memory package root: a package.json whose "files" manifest lists
 * the shipped skills plus the source SKILL.md for each. Returns the install
 * context and a buffer that captures the printed output lines.
 */
function setup(
  files: string[] = [`.claude/skills/${SKILL_A}`, `.claude/skills/${SKILL_B}`],
): Harness {
  const fs = new InMemoryFileSystem();
  fs.writeFile(`${PKG_ROOT}/package.json`, JSON.stringify({ files }));
  fs.writeFile(`${SOURCE}/${SKILL_A}/SKILL.md`, CONTENT_A);
  fs.writeFile(`${SOURCE}/${SKILL_B}/SKILL.md`, CONTENT_B);
  const lines: string[] = [];
  const context: InstallSkillsContext = {
    fs,
    pkgRoot: PKG_ROOT,
    write: (line) => lines.push(line),
  };
  return { fs, lines, context };
}

function seedDest(fs: InMemoryFileSystem, skill: string, content: string): void {
  fs.mkdir(`${DEST}/${skill}`, { recursive: true });
  fs.writeFile(`${DEST}/${skill}/SKILL.md`, content);
}

describe("runInstallSkills", () => {
  describe("clean destination", () => {
    it("writes the shipped content for every skill in the manifest", () => {
      const { fs, context } = setup();

      runInstallSkills({ dir: DEST }, context);

      expect(fs.readFile(`${DEST}/${SKILL_A}/SKILL.md`)).toBe(CONTENT_A);
      expect(fs.readFile(`${DEST}/${SKILL_B}/SKILL.md`)).toBe(CONTENT_B);
    });

    it("creates missing destination directories recursively", () => {
      const { fs, context } = setup();

      // DEST and its parent do not exist yet.
      expect(fs.exists(DEST)).toBe(false);
      runInstallSkills({ dir: DEST }, context);

      expect(fs.exists(`${DEST}/${SKILL_A}`)).toBe(true);
    });

    it("prints an installed line naming the destination path for each skill", () => {
      const { lines, context } = setup();

      runInstallSkills({ dir: DEST }, context);

      expect(lines).toEqual([
        `installed ${SKILL_A} → ${nodePath.join(DEST, SKILL_A, "SKILL.md")}\n`,
        `installed ${SKILL_B} → ${nodePath.join(DEST, SKILL_B, "SKILL.md")}\n`,
      ]);
    });
  });

  describe("destination already up-to-date", () => {
    it("does not rewrite a byte-identical file and reports up-to-date", () => {
      const { fs, lines, context } = setup();
      seedDest(fs, SKILL_A, CONTENT_A);
      seedDest(fs, SKILL_B, CONTENT_B);

      runInstallSkills({ dir: DEST }, context);

      expect(fs.readFile(`${DEST}/${SKILL_A}/SKILL.md`)).toBe(CONTENT_A);
      expect(lines).toEqual([`up-to-date ${SKILL_A}\n`, `up-to-date ${SKILL_B}\n`]);
    });

    it("reports every skill up-to-date when run twice with no changes", () => {
      const first = setup();
      runInstallSkills({ dir: DEST }, first.context);

      const second: InstallSkillsContext = { ...first.context, write: () => {} };
      const secondLines: string[] = [];
      runInstallSkills({ dir: DEST }, { ...second, write: (l) => secondLines.push(l) });

      expect(secondLines).toEqual([`up-to-date ${SKILL_A}\n`, `up-to-date ${SKILL_B}\n`]);
    });
  });

  describe("diverged content without --force", () => {
    it("leaves the edited file untouched and reports skipped", () => {
      const { fs, lines, context } = setup();
      const userEdits = "# User-edited version";
      seedDest(fs, SKILL_A, userEdits);

      runInstallSkills({ dir: DEST }, context);

      expect(fs.readFile(`${DEST}/${SKILL_A}/SKILL.md`)).toBe(userEdits);
      expect(lines[0]).toBe(`skipped ${SKILL_A} (diverged; use --force to overwrite)\n`);
    });

    it("still installs other absent skills when one has diverged", () => {
      const { fs, lines, context } = setup();
      seedDest(fs, SKILL_A, "# My custom version");

      runInstallSkills({ dir: DEST }, context);

      expect(lines[0]).toBe(`skipped ${SKILL_A} (diverged; use --force to overwrite)\n`);
      expect(lines[1]).toBe(`installed ${SKILL_B} → ${nodePath.join(DEST, SKILL_B, "SKILL.md")}\n`);
      expect(fs.readFile(`${DEST}/${SKILL_B}/SKILL.md`)).toBe(CONTENT_B);
    });
  });

  describe("diverged content with --force", () => {
    it("overwrites the edited file with shipped content and reports overwritten", () => {
      const { fs, lines, context } = setup();
      seedDest(fs, SKILL_A, "# User-edited version");
      seedDest(fs, SKILL_B, CONTENT_B);

      runInstallSkills({ dir: DEST, force: true }, context);

      expect(fs.readFile(`${DEST}/${SKILL_A}/SKILL.md`)).toBe(CONTENT_A);
      expect(lines[0]).toBe(`overwritten ${SKILL_A}\n`);
    });
  });

  describe("manifest derivation", () => {
    it("installs only entries under .claude/skills/, ignoring other files", () => {
      const { fs, lines, context } = setup(["dist", "README.md", `.claude/skills/${SKILL_A}`]);

      runInstallSkills({ dir: DEST }, context);

      expect(fs.exists(`${DEST}/${SKILL_A}/SKILL.md`)).toBe(true);
      expect(fs.exists(`${DEST}/${SKILL_B}/SKILL.md`)).toBe(false);
      expect(lines).toEqual([
        `installed ${SKILL_A} → ${nodePath.join(DEST, SKILL_A, "SKILL.md")}\n`,
      ]);
    });

    it("installs nothing and prints nothing when the manifest lists no skills", () => {
      const { fs, lines, context } = setup(["dist"]);

      runInstallSkills({ dir: DEST }, context);

      expect(lines).toEqual([]);
      expect(fs.exists(DEST)).toBe(false);
    });
  });
});

