src/daemon/build-id.test.ts.source:
import { beforeEach, describe, expect, it, vi } from "vitest";
import { isSameBuild, readBuildId } from "./build-id.js";

const mockStatSync = vi.fn();

vi.mock("node:fs", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:fs")>();
  return { ...actual, statSync: (...args: unknown[]) => mockStatSync(...args) };
});

describe("isSameBuild", () => {
  it.each([
    { daemon: 1700000000000, local: 1700000000000, same: true, desc: "same build on both sides" },
    {
      daemon: 1700000000000,
      local: 1700000000001,
      same: false,
      desc: "daemon on a different build",
    },
    // 0 is a valid mtime, so it must not be read as "missing" via truthiness.
    { daemon: 0, local: 0, same: true, desc: "an epoch mtime, which is a real value" },
    { daemon: null, local: null, same: true, desc: "neither side running a build" },
    { daemon: 1700000000000, local: null, same: false, desc: "only the daemon on a build" },
    { daemon: null, local: 1700000000000, same: false, desc: "only this side on a build" },
    { daemon: undefined, local: 1700000000000, same: false, desc: "a daemon omitting the field" },
    { daemon: "1700000000000", local: 1700000000000, same: false, desc: "a non-numeric build id" },
  ])("$desc", ({ daemon, local, same }) => {
    expect(isSameBuild(daemon, local)).toBe(same);
  });
});

describe("readBuildId", () => {
  beforeEach(() => {
    mockStatSync.mockReset();
  });

  it("returns the entry file's modification time", () => {
    mockStatSync.mockReturnValue({ mtimeMs: 1700000000000 });

    expect(readBuildId()).toBe(1700000000000);
  });

  it("returns null when the entry cannot be read", () => {
    mockStatSync.mockImplementation(() => {
      throw new Error("ENOENT");
    });

    expect(readBuildId()).toBeNull();
  });
});

src/daemon/self-write-state.test.ts.source:
import { describe, expect, it } from "vitest";
import { InMemoryFileSystem } from "../ports/in-memory-filesystem.js";
import { createSelfWriteState, getSharedFileSystem } from "./self-write-state.js";

describe("createSelfWriteState", () => {
  it("suppresses exactly the next event for a path written through its filesystem", () => {
    const state = createSelfWriteState(new InMemoryFileSystem());

    state.fileSystem.writeFile("/w/written-by-daemon.ts", "export const x = 1;\n");

    expect(state.shouldSuppress("/w/written-by-daemon.ts")).toBe(true);
    // The entry is consumed on match — a second check on the same untouched
    // file must not suppress again, or a later genuine external edit to it
    // would be silently dropped.
    expect(state.shouldSuppress("/w/written-by-daemon.ts")).toBe(false);
  });

  it("never suppresses a path it has not seen written", () => {
    const state = createSelfWriteState(new InMemoryFileSystem());

    expect(state.shouldSuppress("/w/never-touched.ts")).toBe(false);
  });

  it("does not record a write made around it, straight to the underlying filesystem", () => {
    const inner = new InMemoryFileSystem();
    const state = createSelfWriteState(inner);

    inner.writeFile("/w/written-around-the-back.ts", "export const y = 1;\n");

    expect(state.shouldSuppress("/w/written-around-the-back.ts")).toBe(false);
  });

  it("keeps each state's ledger to itself", () => {
    const inner = new InMemoryFileSystem();
    const one = createSelfWriteState(inner);
    const two = createSelfWriteState(inner);

    one.fileSystem.writeFile("/w/only-known-to-one.ts", "export const z = 1;\n");

    expect(two.shouldSuppress("/w/only-known-to-one.ts")).toBe(false);
  });
});

describe("the daemon's shared filesystem", () => {
  it("is one instance, so every dispatched operation records into the same ledger", () => {
    expect(getSharedFileSystem()).toBe(getSharedFileSystem());
  });
});

src/domain/errors.test.ts.source:
import { describe, expect, it } from "vitest";
import { EngineError } from "./errors.js";

describe("EngineError", () => {
  it("constructs with message and code", () => {
    const err = new EngineError("file missing", "FILE_NOT_FOUND");
    expect(err.message).toBe("file missing");
    expect(err.code).toBe("FILE_NOT_FOUND");
    expect(err.name).toBe("EngineError");
    expect(err instanceof Error).toBe(true);
    expect(err instanceof EngineError).toBe(true);
  });

  it("is() returns true for any EngineError when no code given", () => {
    const err = new EngineError("oops", "SYMBOL_NOT_FOUND");
    expect(EngineError.is(err)).toBe(true);
  });

  it("is() returns true for matching code", () => {
    const err = new EngineError("oops", "SYMBOL_NOT_FOUND");
    expect(EngineError.is(err, "SYMBOL_NOT_FOUND")).toBe(true);
  });

  it("is() returns false for wrong code", () => {
    const err = new EngineError("oops", "SYMBOL_NOT_FOUND");
    expect(EngineError.is(err, "FILE_NOT_FOUND")).toBe(false);
  });

  it("is() returns false for plain Error", () => {
    const err = new Error("plain");
    expect(EngineError.is(err)).toBe(false);
  });

  it("is() returns false for non-error values", () => {
    expect(EngineError.is(null)).toBe(false);
    expect(EngineError.is(undefined)).toBe(false);
    expect(EngineError.is("string")).toBe(false);
    expect(EngineError.is(42)).toBe(false);
  });
});

src/utils/resolve-path-params.test.ts.source:
import * as path from "node:path";
import { describe, expect, it } from "vitest";
import { resolveRelativePaths } from "./resolve-path-params.js";

describe("resolveRelativePaths", () => {
  it("resolves relative path params to absolute using workspace", () => {
    const params: Record<string, unknown> = { file: "src/utils.ts", line: 1 };
    resolveRelativePaths(params, ["file"], "/workspace");
    expect(params.file).toBe(path.join("/workspace", "src/utils.ts"));
  });

  it("leaves absolute paths unchanged", () => {
    const params: Record<string, unknown> = { file: "/abs/src/utils.ts" };
    resolveRelativePaths(params, ["file"], "/workspace");
    expect(params.file).toBe("/abs/src/utils.ts");
  });

  it("leaves non-string params unchanged", () => {
    const params: Record<string, unknown> = { line: 42 };
    resolveRelativePaths(params, ["line"], "/workspace");
    expect(params.line).toBe(42);
  });

  it("resolves multiple path params in one call", () => {
    const params: Record<string, unknown> = {
      oldPath: "src/a.ts",
      newPath: "src/b.ts",
    };
    resolveRelativePaths(params, ["oldPath", "newPath"], "/workspace");
    expect(params.oldPath).toBe(path.join("/workspace", "src/a.ts"));
    expect(params.newPath).toBe(path.join("/workspace", "src/b.ts"));
  });

  it("ignores path params not present in params object", () => {
    const params: Record<string, unknown> = { file: "src/a.ts" };
    resolveRelativePaths(params, ["file", "extra"], "/workspace");
    expect(params.file).toBe(path.join("/workspace", "src/a.ts"));
    expect(params.extra).toBeUndefined();
  });

  it("does not modify params when pathParams list is empty", () => {
    const params: Record<string, unknown> = { file: "src/a.ts" };
    resolveRelativePaths(params, [], "/workspace");
    expect(params.file).toBe("src/a.ts");
  });
});

src/adapters/cli/classify-error.test.ts.source:
import { describe, expect, it } from "vitest";
import { classifyDaemonError } from "./classify-error.js";

describe("classifyDaemonError", () => {
  it("returns DAEMON_STARTING for ECONNREFUSED (daemon not yet listening)", () => {
    const err = Object.assign(new Error("connect ECONNREFUSED /tmp/sock"), {
      code: "ECONNREFUSED",
    });
    expect(classifyDaemonError(err)).toBe("DAEMON_STARTING");
  });

  it("returns DAEMON_STARTING for ENOENT (socket file missing)", () => {
    const err = Object.assign(new Error("no such file or directory"), { code: "ENOENT" });
    expect(classifyDaemonError(err)).toBe("DAEMON_STARTING");
  });

  it("returns DAEMON_STARTING for ECONNRESET (daemon crashed mid-response)", () => {
    const err = Object.assign(new Error("read ECONNRESET"), { code: "ECONNRESET" });
    expect(classifyDaemonError(err)).toBe("DAEMON_STARTING");
  });

  it("returns DAEMON_STARTING for timeout (daemon slow to respond)", () => {
    const err = new Error("callDaemon timed out after 30000ms");
    expect(classifyDaemonError(err)).toBe("DAEMON_STARTING");
  });

  it("returns INTERNAL_ERROR for JSON parse failures (malformed daemon response)", () => {
    const err = new SyntaxError("Unexpected token < in JSON at position 0");
    expect(classifyDaemonError(err)).toBe("INTERNAL_ERROR");
  });

  it("returns INTERNAL_ERROR for unexpected Error types", () => {
    expect(classifyDaemonError(new Error("something else went wrong"))).toBe("INTERNAL_ERROR");
  });

  it("returns INTERNAL_ERROR for non-Error values", () => {
    expect(classifyDaemonError("string error")).toBe("INTERNAL_ERROR");
    expect(classifyDaemonError(null)).toBe("INTERNAL_ERROR");
    expect(classifyDaemonError(42)).toBe("INTERNAL_ERROR");
  });
});

src/daemon/serialise-response.test.ts.source:
import { describe, expect, it } from "vitest";
import type { DispatchResponse } from "./dispatcher.js";
import { serialiseResponse } from "./serialise-response.js";

describe("serialiseResponse", () => {
  it("returns the JSON of an ordinary success response followed by a newline", () => {
    const response: DispatchResponse = { status: "success", filesModified: ["a.ts"] };

    expect(serialiseResponse(response)).toBe(
      `${JSON.stringify({ status: "success", filesModified: ["a.ts"] })}\n`,
    );
  });

  it("returns the JSON of an ordinary error response followed by a newline", () => {
    const response: DispatchResponse = {
      status: "error",
      error: "FILE_NOT_FOUND",
      message: "File not found: a.ts",
    };

    expect(serialiseResponse(response)).toBe(`${JSON.stringify(response)}\n`);
  });

  it("returns an INTERNAL_ERROR envelope instead of throwing when the response is circular", () => {
    const circular: Record<string, unknown> = { status: "success" };
    circular.self = circular;

    expect(serialiseResponse(circular as unknown as DispatchResponse)).toBe(
      `${JSON.stringify({
        status: "error",
        error: "INTERNAL_ERROR",
        message: "response could not be serialised",
      })}\n`,
    );
  });
});
